"""An 'on' spelling/preposition detector, sensitive to token boundaries.

The strongest spelling response is to an o followed by an n in a new
fragment (including transliterated alphabets and katakana). Short, rare 'on'
fragments respond more than long words containing those letters. The
preposition has a separate, smaller response, weakened after verbs that
already select 'on'. Repeated on-syllables are suppressed, while short
continuations of an on-fragment retain some response. One-token memory
resets at document boundaries. Many lexical exceptions remain unexplained.
"""
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency
import regex
import wordnet

READS = ()
ALPHABET = regex.compile(r'^[\p{Latin}\p{Greek}\p{Cyrillic}\p{M}-]+$')
KATAKANA = regex.compile(r'^[\p{Katakana}ー]+$')
# Prepositions expressing 'on' or 'onto', in several languages.
PREPOSITIONS = {
    'upon': 0.98, 'onto': 0.39, 'sur': 1.03, 'sul': 0.48,
    'su': 0.12, 'sobre': 0.49, 'auf': 0.33, 'på': 0.91,
    'na': 0.16, 'على': 0.64,
}


@lru_cache(maxsize=32768)
def describe(token):
    word = token.strip()
    script = ('alphabet' if ALPHABET.fullmatch(word) else
              'katakana' if KATAKANA.fullmatch(word) else 'other')
    spelling = anyascii(word).lower().strip('-') if script != 'other' else word.lower()
    return word, spelling, script, bool(token and token[0].isspace())


@lru_cache(maxsize=8192)
def frequency(word):
    return zipf_frequency(word, 'en')


@lru_cache(maxsize=8192)
def verb_roots(word):
    return set(wordnet.base_forms(word)) | {word}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word, spelling, script, leading = describe(token)
    oldword, old, oldscript, _ = describe(previous)
    n = len(spelling)
    value = 0.0

    if leading and word.lower() in PREPOSITIONS:
        value = PREPOSITIONS[word.lower()]
    elif (not leading and script == oldscript == 'alphabet' and
          spelling.startswith('on') and regex.search(r'on[^aeiou]{0,2}$', old)):
        # A second nasal syllable, as in phon-on or monot-onic.
        value = -3.15 if spelling == 'on' else -2.5
    elif spelling == 'on' and script == 'alphabet':
        if leading:
            value = 1.05 if word[0].isupper() else 0.89
            roots = verb_roots(oldword.lower())
            if roots & {'base', 'depend', 'rely'}:
                value = 0.28
            elif roots & {'focus', 'concentrate', 'center', 'go'}:
                value = 0.38
            elif oldword.lower() in {'so', 'on'} or not previous.strip():
                value = 0.02
        else:
            value = 1.0
    elif (not leading and script == oldscript and
          script in {'alphabet', 'katakana'} and
          old.endswith('o') and spelling.startswith('n')):
        value = 4.0 if script == 'katakana' else 2.8 - 0.5 * min(len(old)-1, 2)
    elif (not leading and script == oldscript == 'alphabet' and
          old.endswith('on') and
          not old.endswith(('ion', 'non')) and spelling[:1].isalpha()):
        vowel = spelling[0] in 'aeiouy'
        value = (2.15 if vowel else 0.71) if n == 1 else (0.40 if vowel else 0.26)
        if len(old) > 4:
            value *= 0.3
    elif script == 'alphabet' and 'on' in spelling:
        if leading:
            value = 0.13 if n <= 5 else 0.06 if n == 6 else 0.02
        elif spelling.startswith('on'):
            value = 0.78 if n <= 5 else 0.36
        elif n == 3:
            value = 0.35 if frequency(spelling) >= 3 else 1.4
        elif n == 4:
            value = 0.4
        elif n == 5:
            value = 0.1
        else:
            value = 0.01
    return (doc, token), value

"""A surface-formatting detector, quiet on most ordinary text.

Positive rules recognize code underscores, numbers followed by time/date
separators, printf conversions, and textual or raw byte-encoding markers.
GitHub's domain ending has a negative response. Homogeneous document prefixes of
control/decorative characters have their own large response. The short text
memory and the homogeneous-prefix flag reset at each new document.
Irregular word-specific and document-initial spikes are left unmodeled.
"""
import re

READS = ()
PRINTF = re.compile(r'%[-+ #0]*\d*(?:\.\d+)?\Z')
SHORT_NUMBER = re.compile(r'(?<!\d)(\d{1,2})\Z')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        tail, first, uniform = '', s, True
    else:
        _, tail, first, uniform = carry
        uniform = uniform and s == first
    b = prefix.token_bytes[-1]
    number = SHORT_NUMBER.search(tail)
    value = 0.0
    if uniform and s in ('··', '^^^^', '\r', '//\n'):
        value = {'··': 2.52, '^^^^': 5.13, '\r': 11.6,
                 '//\n': 13.94}[s]
    elif s == '\x00':
        value = 0.18 if tail.endswith(' ') else 1.65
    elif s == '\r':
        value = 0.15
    elif s == '__':
        value = 1.12
    elif s == ' __':
        value = 0.78 if tail.endswith('def') else 0.22
    elif len(s) == 1 and s in 'sdvfxqwcgr' and PRINTF.search(tail):
        value = 2.05 if s in 'dv' else 1.6
    elif s in (':', '/') and number:
        digits = number[1]
        before = tail[:number.start()]
        boundary = not before or before[-1].isspace()
        attached = before[-1:].isalnum() and not before.endswith('T')
        if not attached and not before.endswith('_'):
            if s == ':':
                value = 0.9 if len(digits) == 2 else 0.35
                if int(digits) > 23:
                    value = 0.35
                if not boundary:
                    value *= 0.55
                if before.endswith(':'):
                    value = 0.2
                if re.search(r'(?:\bat|\baround|上午|下午|в)\s*\Z',
                             before, re.IGNORECASE):
                    value = 1.1
            else:
                value = (1.0 if len(digits) == 2 else 0.55)
                if not 1 <= int(digits) <= 12:
                    value = 0.3
                if not boundary:
                    value = 0.25
    elif s in ('月', '월') and tail[-1:].isdigit():
        value = 1.6
    elif re.fullmatch(r'x[0-9a-fA-F]?', s) and re.search(r'(?<!\d)0\Z', tail):
        value = 1.05
    elif re.fullmatch(r'\\+x[0-9a-fA-F]?', s):
        value = {'e': 1.08, 'c': 0.55, 'a': 0.8}.get(s[-1], 0.48)
    elif re.fullmatch(r'x[cde]', s) and tail.endswith('\\'):
        value = 2.0
    elif s.lstrip() == '&#':
        value = 1.05
    elif s == "\\'":
        value = 0.95
    elif b.lstrip() == b'\xc2':  # lead byte for U+0080--U+00BF symbols
        value = 0.98
    elif b.lstrip() == b'\xe2\x80':  # beginning of Unicode General Punctuation
        value = 0.53
    elif s == 'Ђ' and tail.endswith('в'):  # mojibake punctuation
        value = 0.9
    elif s in ('â', ' â'):
        value = 1.0 if s.startswith(' ') else 0.5
    elif s == '\xa0' and tail.endswith('–'):
        value = 1.6
    elif s == '.com' and re.search(
            r'(?:^|[^.\w])(?:github|raw\.githubusercontent)\Z',
            tail, re.IGNORECASE):
        value = -3.5
    elif s.startswith('/') and re.search(
            r'(?:^|[^.\w])github\.com\Z', tail, re.IGNORECASE):
        value = -0.7
    elif s == '":':
        value = 0.35 if tail.endswith('name') else 0.075
    elif s.startswith('}') and s.strip() == '}':
        value = 0.5 if re.search(r'}\s*\Z', tail) else 0.0
        if value == 0.0 and '\n' in s:
            value = 0.095
    elif len(s) == 1 and s in 'ABCDEF' and re.search(r'%[0-9A-F]\Z', tail):
        value = 0.9
    elif s == '!(':
        value = 0.5
    elif s == ' `':
        value = 0.075
    return (doc, (tail + s)[-100:], first, uniform), value

"""Approximate a nu-versus-nasal-stem spelling feature.

Nu syllables give negative values; nehmen/nahm/nimm-like stems give
positive ones. Token-split spellings are recognized using a 24-character
tail, reset at document boundaries. Short nu spellings are distinguished
from complete words such as number or nuclear. A secondary rule responds
to the colon in a document-initial Title: field. All other cases return
zero. The constants are training-set averages, not exact activations.
"""
import re
import regex
from functools import lru_cache
from pypinyin import lazy_pinyin

READS = ()

@lru_cache(maxsize=4096)
def chinese_nu(s):
    return (len(s) == 1 and regex.fullmatch(r'\p{Script=Han}', s)
            and lazy_pinyin(s) == ['nu'])

PREFIXES = ('an', 'auf', 'ab', 'ein', 'über', 'ver', 'ent', 'zu',
            'bei', 'mit', 'aus', 'unter')


def activation(previous, current):
    p, s = previous.lower(), current.lower()
    c = s.strip()
    if not c:
        return 0.0
    joined = not s[0].isspace()
    if current == ':' and (previous == 'Title' or
                           previous.endswith('<|endoftext|>Title')):
        return 7.6
    if c == 'ν':
        if re.search(r'[µμ]\s*$', p):
            return -5.33
        if len(regex.findall(r'\p{Script=Greek}', p)) >= 2:
            return 0.0
        if s[0].isspace() or not regex.search(r'\p{Script=Greek}$', previous):
            return -1.53
        return 0.0
    if c in ('ぬ', 'ヌ', 'ニュ', '누', '뉴'):
        return -3.01
    if chinese_nu(c):
        return -0.72
    if c == 'ну':
        return -4.51 if not joined else -0.8
    if joined and p.endswith('н'):
        if c.startswith('ю'):
            return -4.19
        if re.search(r'(?:^|\s)н$', p) and c.startswith('у'):
            return -3.74
    # German/Dutch take stems and their characteristic token-split endings.
    if c in ('nom', 'nah', 'nehm', 'nehmen', 'nahme', 'nimm'):
        if p.rstrip().endswith(PREFIXES):
            return 4.7
    if re.fullmatch(r'n[ae]h(?:m(?:e[nr]?|t)?|[er])?', c):
        return 3.78
    if c in ('nam', 'nom', 'nim', 'nem'):
        return 0.53
    if joined:
        if p.endswith('n'):
            if c in ('ah', 'eh'):
                return 4.28
            if c in ('ommen', 'emen', 'imm', 'immen'):
                return 4.77
        if re.search(r'n[ae]h$', p) and re.fullmatch(r'm(?:e[nr]?|t)?', c):
            return 5.44
        if re.search(r'n[oi]m$', p) and c in ('m', 'mt', 'men'):
            return 7.49
        if re.search(r'n[ae]$', p) and c in ('h', 'he', 'her', 'hm', 'em', 'am'):
            return 3.68
        if p.endswith('n') and c in ('am', 'em', 'im'):
            if re.search('[bcdfghjklmnpqrstvwxyz]n$', p):
                return 2.6
            return 0.83
    if (joined and p.endswith('nu') and
            c in ('ance', 'ances', 'anced', 'end', 'ends', 'ating')):
        return -2.76
    # Short Latin-script nu syllables; not num-, null-, or nucle- words.
    if c == 'nu':
        return -4.14
    if re.fullmatch(r'(?:[aeiou]|g|ge)?nu', c):
        return -3.42
    if c in ('nut', 'anut'):
        return -3.02
    if c == 'nun':
        return -2.85 if 'N' in current else -1.47
    if c == 'nue':
        return -4.13
    if c.startswith('nuanc'):
        return -2.92
    if c.startswith('nuis'):
        return -2.42
    if c in ('nus', 'anus', 'enus', 'genus'):
        return -0.76
    if c in ('nuts', 'nude'):
        return -1.63
    if c == 'enum' and current.isupper():
        return -2.16
    if joined and p.endswith('n') and c.startswith(('u', 'ü', 'ú', 'ù')):
        if len(c) >= 5:
            return -0.26
        if len(c) == 1:
            return -4.17
        if c.startswith(('um', 'us')):
            return -1.95
        if len(c) == 2 and c[1] not in 'mnrsei':
            return -3.89
        if c.startswith(('ue', 'ui')):
            return -1.91
        if c.startswith(('ur', 'un')):
            return -0.8
        return -1.42
    if c.startswith('neut'):
        return -0.23
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    current = prefix.token_strings[-1]
    value = activation(tail, current)
    return (doc, (tail + current)[-24:]), value

"""Recognize namespace names and declarations, especially at the start of code.

A bare namespace declaration is stronger than a namespace variable or prose mention.
Related signals include Java package-domain prefixes, module exports, test-suite
names, descriptive strings, and class declarations. Small rules cover metadata,
path/diff markers and typography. A weak negative baseline is used for initial
words; document boundaries reset the short text history.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0)
    _, recent, previous, position = carry
    s = prefix.token_strings[-1]
    word = s.strip()
    before = recent.rsplit('\n', 1)[-1]
    line_start = not before.strip()
    value = -0.003

    # Namespace keywords, fields and compound identifiers.
    if word.lower().strip('._') in {'namespace', 'namespaces'}:
        if word == 'namespace':
            if line_start and not s.startswith((' ', '\t')):
                if '<?php' in recent:
                    value = 7.4
                elif re.search(r'#(?:include|define)|using |namespace ', recent):
                    value = 13.1
                else:
                    value = 8.0
            elif previous.strip() == 'using' or re.search(r'}\s*//[^\n]*$', before):
                value = 7.0
            elif s.startswith((' ', '\t')):
                value = 2.8
            else:
                value = 2.6 if before.rstrip().endswith('(') else 0.5
        else:
            value = 2.5
    elif re.search(r'namespac(?:ed|es)$', recent[-16:] + s, re.I):
        value = 3.8

    # Java's reverse-domain package names, not ordinary uses of "package".
    elif previous == 'package' and word in {'com', 'org', 'net', 'io', 'ns'}:
        if word == 'com':
            value = 7.73 if position == 1 else 2.6
        elif word == 'org':
            value = 5.35 if position == 1 else 3.5
        else:
            value = 2.3
    elif word == 'module':
        if s.startswith('\t'):
            value = 1.4
        elif position == 0:
            value = 5.75 if s == 'module' else 1.7
        elif line_start:
            value = 3.5
        elif previous.strip() in {'typeof', '='}:
            value = 1.5
        elif previous.endswith(("('", '("')):
            value = 1.3
    elif word == 'class' and previous.strip() in {'public', 'final', 'partial'}:
        value = 0.85
    elif word == 'using' and line_start:
        value = -0.98 if position == 0 else 0.9
    elif (word == 'region' and previous.strip() == '#') or word == '#region':
        value = 0.7
    elif word in {'#if', '#ifdef', '#ifndef'}:
        value = 0.9
    elif word == 'php' and previous == '<?':
        value = 1.2
    elif word in {"('", '("', '(`'} and previous.strip() in {'describe', 'suite'}:
        value = 4.0
    elif s == 'describe' and line_start and re.search(
        r'\b(?:import|const|var|function)\b|[{};]', recent
    ):
        value = 4.0
    elif s == '(function' and line_start and position > 0:
        value = 6.5
    elif word == '()' and before.strip() == '(function':
        value = 2.5
    elif word == '(exports' and previous.strip() in {'function', 'factory'}:
        value = 3.0
    elif word == '(global' and previous == '(function':
        value = 3.3
    elif word in {"('", '("', '(`', "='", '="', "'", '"'}:
        if re.search(r'(setTitle|set_caption|ArgumentParser)$', before):
            value = 2.7
        elif re.search(r'(?:title|desc|description|Description|label|Name)$', before):
            value = 0.9
        elif re.search(r'\bCOMMENT\s*$', before):
            value = 0.7
    elif previous.strip().lower() == 'no' and word.lower() in {
        'solution', 'solutions', 'wonder'
    }:
        value = 0.74
    elif previous == 'posted' and word == 'by' and before.strip() == 'posted':
        value = 2.5
    elif previous == 'Title' and word == ':' and position == 1:
        value = -2.55

    # Small typographic/path signals, separate from the declaration response.
    elif s == '··':
        value = -2.03
    elif word == '@@':
        value = 0.72 if s.startswith(' ') else 0.25
    elif s == '/workspace':
        value = 0.26
    elif s.isspace() and '\n' not in s and len(s) >= 3:
        value = -0.04

    if position == 0 and s and s[0].isalpha() and s not in {'module', 'window'}:
        value = -0.35 if s[0].isascii() else -0.1
    elif s == 'window' and position == 0:
        value = 2.3
    return (doc, (recent + s)[-600:], s, position + 1), float(value)

"""A pulse on the initial run of identical tokens in each document.

The pulse is strongest for text and chat boundaries, weaker for numbers,
punctuation and spaces. English grammatical classes give a coarse adjustment
to its size. After the first different token, predict zero, not another pulse.
This captures the onset effect but not each token's idiosyncratic amplitude.
"""
import wordnet

READS = ()

COORDINATORS = set('and but or nor for yet so'.split())
AUXILIARIES = set(
    'am is are was were be been being do does did have has had can could '
    'shall should will would may might must'.split()
)


def onset_size(s):
    t = s.strip()
    if s.startswith('<|'):
        return 9.6
    if not t:
        return 7.3 if '\t' in s else 3.6 if '\n' in s else 1.6
    if t.isdigit():
        return 5.1
    if '\ufffd' in t:
        return 5.0
    if not any(c.isalpha() for c in t):
        if set(t) == {'#'}:
            return 0.5
        return 2.0 if s.startswith(' ') else 3.6
    if not t.isascii():
        return 7.2
    word = t.lower()
    if word == 'the':
        return 6.2
    if word in COORDINATORS:
        return 5.9
    if word in AUXILIARIES:
        return 6.6
    pos = wordnet.parts_of_speech(word)
    if pos and not (pos & {'noun', 'verb'}):
        return 10.0
    if t.isupper():
        return 6.8
    return 8.4 if t.istitle() and not s.startswith(' ') else 7.6


def step(carry, prefix, upstream):
    token = prefix.token_ids[-1]
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        value = onset_size(prefix.token_strings[-1])
        return (document, token, value, True), value
    doc, first, value, initial_run = carry
    initial_run = initial_run and token == first
    return (doc, first, value, initial_run), value if initial_run else 0.0

"""Approximate the component's backslash-escaping responses.

Repeated backslashes are positive, with quote-adjacency and run-length
adjustments. Recent TeX commands instead select a negative line-break
response. Escaped punctuation and JSON key/value separators have smaller
positive responses. A weak negative boundary correction is larger on
capitalized words. Keep only 256 characters of context; reset at document
boundaries. This does not attempt to explain unrelated lexical responses.
"""
import re

READS = ()
MATH = re.compile(
    r'(?<!\\)\\(?:frac|left|right|begin|end|sqrt|sum|cdot|mu|alpha|beta|theta|pi|'
    r'lim|vec|quad|mbox|text|color|overline|partial|hat|pmatrix|big)(?![A-Za-z])'
)
RUNS = re.compile(r'\\+')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    s = prefix.token_strings[-1]
    previous_slashes = len(tail) - len(tail.rstrip('\\'))
    leading_slashes = len(s) - len(s.lstrip('\\'))
    runs = [len(m.group()) for m in RUNS.finditer(s)]
    run = max(runs + [previous_slashes + leading_slashes
                     if leading_slashes else 0])
    math = bool(MATH.search(tail))
    value = -0.003
    if run >= 2:
        if math:
            value = -5.0
        elif run == 2:
            value = 5.0 if tail.endswith(('"', "'")) else 3.0
            if '"' in s or "'" in s:
                value = 3.8
        elif run == 3:
            value = 6.3 if s.endswith('"') else 3.6
        else:
            value = 6.9
    elif s == '":':
        value = 0.38 if tail.endswith('"name') else 0.21
    elif s.startswith('\\"') and s.endswith(':'):
        value = 0.45
    elif '\\' in s and not s.strip(' \\'):
        value = 2.0 if previous_slashes % 2 and s.startswith(' ') else 0.03
    elif s.lstrip().startswith('\\') and len(s.lstrip()) > 1:
        ch = s.lstrip()[1]
        if ch in '$_[{':
            value = 1.0
        elif ch in '*!.':
            value = 3.5
    elif previous_slashes:
        if s == 'cr':  # TeX's other spelling of a row break.
            value = -8.0
        elif math and previous_slashes >= 2 and '\n' in s:
            value = -2.5
        elif s and s[0] in '*!.-':
            value = 3.3
        elif s and s[0] in '_$':
            value = 2.0
        elif s.startswith('['):
            value = 0.9
        elif s.startswith('{'):
            value = 0.2
    if not tail or tail.endswith('<|endoftext|>'):
        word = s.lstrip()
        if word and word[0].isascii() and word[0].isalpha():
            value -= 0.5 if word[0].isupper() else 0.22
        elif not tail and not s.startswith('<|'):
            value -= 0.2
    return (doc, (tail + s)[-256:]), value

"""A sparse collection of surface cues, not a single semantic category.

The strongest negative cue is the colon in a document-opening Title: header.
Others are Chinese 具有 ('possess/have'), Markdown list brackets, JavaScript
'[object ...]' tags, and Rust feature attributes. Repeated interpuncts give
an opposite response. A small positive baseline handles document starts.
Away from these cues and starts, output is zero. Fine context effects are omitted.
"""

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous, line = 0, '', ''
    else:
        position, previous, line = carry[1] + 1, carry[2], carry[3]

    value = 0.0
    if position == 0:
        value = 0.35 if token.startswith('<|') else 0.08

    if token == ':' and previous == 'Title' and position == 1:
        value = -5.956
    elif token == '具有':
        value = -1.13
    elif token == '有的' and previous.endswith('具'):
        value = -0.95
    elif token == ' [' and line.strip() in ('*', '-'):
        value = -0.60
    elif token == 'object' and previous.endswith('[') and '"' in previous:
        value = -0.84
    elif token == 'feature' and previous.endswith('#!['):
        value = -0.98
    elif token == '··' and previous == '··':
        value = 0.61

    line = (line + token).rsplit('\n', 1)[-1][-40:]
    return (doc, position, token, line), value

"""Approximate a sparse lexical response, not a general Chinese detector.

The strongest positive rule is for multi-character Han tokens beginning
with Chinese relational words (from, toward, in, if). Two-character forms
get a larger response; grammatical combinations like '对于' get less.
Time expressions beginning 当 also receive a boost. Japanese の compounds
are positive, whereas 'already' and discourse connectives are negative.
Clause boundaries boost time expressions and strengthen Japanese
connectives. Repeated relational tokens are slightly damped. There is a
separate, coarse first-token correction by script/case/length.
These fitted rules omit many isolated, token-specific responses.
"""
import regex

READS = ()
HAN = regex.compile(r'\A\p{Script=Han}{2,}\Z')
KANA = regex.compile(r'\A\p{Script=Hiragana}+\Z')
FROM = set('从從')
TOWARD = set('对對')
DISPOSAL_PASSIVE = set('把被')
IN = set('在')
MEANS_PURPOSE = set('以为為')
COMPARISON = set('比较較')
CONDITIONAL = set('如若')
TIME_MARKERS = set('当當将將')
RELATORS = (FROM | TOWARD | DISPOSAL_PASSIVE | IN | MEANS_PURPOSE
            | COMPARISON | CONDITIONAL | TIME_MARKERS)
GRAMMATICAL_ENDINGS = set('于於而何此然着著的了为為其你我他她它们們地')
TIME_ENDINGS = set('时時年晚初前下今')
BOUNDARY = regex.compile(r'[。！？!?；;，,、：:（(\n]\s*$')


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        seen, boundary = set(), False
    else:
        _, seen, boundary = carry
    value = -0.001
    if HAN.fullmatch(token):
        ch = token[0]
        value = -0.01
        if ch in RELATORS:
            value += 0.17 if len(token) == 2 else 0.0
            if ch in FROM:
                value += 0.51
            elif ch in TOWARD:
                value += 0.30
            elif ch in IN:
                value += 0.17
            elif ch in DISPOSAL_PASSIVE:
                value += 0.10
            elif ch in CONDITIONAL:
                value += 0.13
            elif ch in MEANS_PURPOSE:
                value += 0.03
            if len(token) == 2 and token[-1] in GRAMMATICAL_ENDINGS:
                value -= 0.26
            if boundary:
                value += 0.07
            if token in seen:
                value -= 0.06
        if ch in '当當' and token[-1] in TIME_ENDINGS:
            value += 0.13 + (0.75 if boundary else 0.0)
        if token.startswith('如果'):
            value += 0.09
        if ch in '的之':
            value += 0.06
    elif KANA.fullmatch(token):
        value = 0.01
        if len(token) > 1 and token.startswith('の'):
            value += 0.11
        if token == 'もう':
            value = -0.9
        elif token in ('でも', 'では', 'なお'):
            value = -0.20 - (0.80 if boundary else 0.0)
    if first:
        s = token.strip()
        value = -0.04
        if s.isascii() and s.isalpha():
            if s[0].isupper():
                value -= 0.21
            if len(s) <= 2:
                value -= 0.07
            if len(s) >= 8:
                value -= 0.13
            if token[0].isspace():
                value -= 0.10
        elif s.isdigit():
            value = 0.17
        elif HAN.fullmatch(s):
            value = -0.40
        elif s and s[0].isupper():
            value = -0.35
    seen.add(token)
    return (doc, seen, bool(BOUNDARY.search(token))), value

"""Respond to a context with no token diversity, and to structured separators.

Most large activations are at document starts (also long repetitions of the
initial token). Their strength varies with writing style: indentation and
numerals are strong; ordinary capitalized words are weak. Once varied text
has appeared, the main rules distinguish quoted key/value separators and
escaped backslashes from TeX's negatively activated row separators.
Token-specific lexical differences are deliberately not memorized.
"""
import re
import unicodedata

READS = ()

# Familiar mathematical typesetting commands, not ordinary string escapes.
TEX = re.compile(
    r'\\(?:begin|end|frac|sqrt|left|right|mathrm|mathbf|mathbb|'
    r'text|quad|qquad|alpha|beta|gamma|theta|phi|lambda|sum|int|'
    r'leq|nonumber|hfill|pmatrix)\b'
)

# Object keys immediately after an opening brace, or an unquoted key after a comma.
FIRST_KEY = re.compile(r'\{\s*[\"\'][^\"\']*$')
PLAIN_KEY = re.compile(r'[{,]\s*(?:[A-Za-z_$][\w$]*|\d+)$')


def start_value(text):
    word = text.strip()
    if text == '<|endoftext|>':
        return -1.1
    if text.startswith('<|'):
        return 0.87
    if not word:
        if '\n' in text or '\r' in text:
            if text.startswith((' ', '\t')):
                return 0.55
            return -0.25 if text.count('\n') > 1 else 0.13
        return 6.2 if text == '\t' else 3.8
    if text.startswith(('//', '/*')):
        return 4.3
    if '\n' in text or '\r' in text:
        if word.startswith(('.', '?', '。')):
            return -0.5
        return 1.8 if any(c in word for c in '(){}[];') else 0.6
    if word.isascii() and word.isdigit():
        return 4.17 if word == '0' else 3.0
    if not word.isascii():
        if all(unicodedata.category(c).startswith('P') for c in word):
            return 0.25
        return 0.2 if word.istitle() else 1.25
    if word.isalpha():
        if word.lower() == 'the':
            return 0.52 if text.startswith(' ') else -0.75
        if word.lower() in {'a', 'an'}:
            return 1.1 if text.startswith(' ') else -0.3
        if word.islower():
            return 2.3
        if text.startswith(' '):
            return 2.5 if len(word) <= 2 else 1.6
        return 0.2 if word.istitle() else 0.6
    if word in {'?', '!'}:
        return 0.4
    if word == '#':
        return 0.25
    if word == '=':
        return 0.65 if not text.startswith(' ') else 3.7
    if word == ':':
        return 0.85
    return 3.2 if text.startswith(' ') else 2.4


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        initial, uniform = token, True
        initial_value, tail = start_value(text), ''
    else:
        _, initial, uniform, initial_value, tail = carry
        uniform = uniform and token == initial

    if uniform:
        value = initial_value
    elif text == 'cr' and tail.endswith('\\'):
        value = -6.0  # TeX's \cr ends a row.
    elif text.count('\\') >= 2 and text.rstrip().endswith('\\\\'):
        value = -2.8 if TEX.search(tail) else 1.25
    elif text.endswith('\":'):
        value = 0.7 if FIRST_KEY.search(tail) else 0.45
    elif text.endswith("':"):
        value = 0.7 if FIRST_KEY.search(tail) else 0.35
    elif text == ':':
        key = PLAIN_KEY.search(tail.replace('\\n', '\n'))
        value = 0.4 if key else 0.0
    elif text.strip() == '=>':
        value = 0.55 if tail.rstrip().endswith(("'", '\"')) else 0.0
    elif text == '\f':
        value = 0.6
    else:
        value = 0.0
    # Bounded history is enough to classify these local separators.
    tail = (tail + text)[-512:]
    return (doc, initial, uniform, initial_value, tail), value

