"""layers.1.mlp.down_proj:5134: a "code-like token" detector that fires on a document's first token.

What it does: this component is silent almost everywhere. It switches on only at the first token
of a document (and at the first token of each packed row, where the model has no earlier text to
look back at). There the activation depends only on the token's own spelling, and it is high
for code-like tokens and low for prose:

- high: tab-indented identifiers (`\\tcurr`, `\\tjson`), snake_case and camelCase names (`_factory`,
  `.student`), short consonant-heavy abbreviations of code (` img`, ` btn`, ` cfg`), code words
  (` data`, ` new`, ` class`);
- low or negative: capitalised English words (`One`, `Oh`, `North`), common function words
  (` the`, ` and`, ` which`, ` an`), non-ASCII text (CJK, Thai, Bengali...), and newlines;
- special chat tokens (`<|im_start|>`, `<|endoftext|>`) are predicted as 0.

At every other position it predicts 0.
"""

import unicodedata

READS = ()

FUNCTION_WORDS = set(
    "a an the and or but of to in on at by for with from as is are was were be it its this that "
    "which who what when where how if then than so not no any each all some into about he she "
    "they we you i me him her them my your his their our would could should will can do does "
    "have has had there here also just only very more".split()
)
VOWELS = set("aeiouAEIOU")


def first_token_activation(token: str) -> float:
    """The activation at a document's first token, as a function of its spelling."""
    if token.startswith("<|") and token.endswith("|>"):
        return 0.0  # chat / end-of-text markers
    text = token.strip()
    letters = [c for c in text if c.isalpha()]
    vowel_share = sum(c in VOWELS for c in letters) / max(1, len(letters))
    score = 2.7
    if token.startswith("\t"):
        score += 2.6  # tab-indented code
    if "_" in token:
        score += 1.6  # snake_case identifiers
    if any(a.islower() and b.isupper() for a, b in zip(token, token[1:])):
        score += 0.7  # camelCase identifiers
    if text[:1].isupper():
        score -= 0.9  # capitalised word
    if token.startswith(" "):
        score += 0.4  # a word that starts a new space-separated piece
    if any(ord(c) > 127 for c in token):
        score -= 1.5  # non-ASCII script
    if "\n" in token or "\r" in token:
        score -= 2.2
    if text.lower() in FUNCTION_WORDS:
        score -= 1.0  # ordinary English function words
    score -= 1.2 * vowel_share  # consonant-heavy abbreviations look like code
    return score


def step(carry, prefix, upstream):
    """The activation at the newest position: nonzero only at a document's first token."""
    t = prefix.position
    starts_document = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not starts_document:
        return carry, 0.0
    return carry, float(first_token_activation(prefix.token_strings[-1]))

