"""Approximate the component's sparse, large responses using text syntax.

URL separators are negative. Branch/error-handling keywords are positive
following a brace or whitespace; 'else' after an indefinite pronoun is negative.
The colon after a document-initial 'Title' has a large positive response.
Repeated middle-dot separators get a smaller positive value. Other activity
is approximated by zero; this does not recover all the small lexical effects.
"""
import re

READS = ()
INDEFINITE = re.compile(r'\b(any|some|every|no)(one|body|thing|where)$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous = '', ''
    else:
        _, tail, previous = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    after_brace = tail.rstrip().endswith('}')
    indented = bool(previous) and previous[-1].isspace()
    value = 0.0

    if token == '://':
        scheme = previous.strip().lower()
        if scheme.endswith('https'):
            value = -1.9
        elif scheme.endswith('http'):
            value = -2.3
        else:
            value = -1.36 if not previous else -0.1
        if scheme in ('http', 'https') and previous[0].isspace():
            value -= 0.2
    elif token == '//' and re.search(r'https?\s*:\s*$', tail, re.I):
        value = -2.6
    elif token == ':' and tail == 'Title':
        value = 10.18
    elif word == 'else' or token == '}else':
        if after_brace or indented or token == '}else' or token.startswith('\t'):
            value = 0.88 if after_brace else 0.78
            if token.startswith('\t') or token == 'else':
                value = 0.64
            elif token == '}else':
                value = 0.55
        else:
            pronoun = INDEFINITE.search(tail.lower())
            if pronoun:
                value = -0.35
            elif tail.endswith((';', ')', ']')):
                value = 0.27
    elif word == 'elseif' and (after_brace or indented):
        value = 0.55
    elif word == 'catch' and (after_brace or indented):
        value = 1.08
    elif word == 'except' and indented:
        value = 0.96
    elif word == 'default' and indented:
        if any(mark in tail for mark in ('break', 'return', 'case', '}')):
            value = 1.2
    elif token == '··' and (not previous or previous == '··'):
        value = 1.2

    return (doc, (tail + token)[-100:], token), value

"""Approximate a spelling-sensitive, multilingual component.

Short er-/ver-/zer- pieces in German or Dutch text receive positive values,
as does the first continuation after such a piece. Recent function words
supply a rough language cue; word frequency excludes common English words.
Latin-derived -vers- pieces instead receive negative values. Cyrillic у and
pairs of middle dots have separate positive responses. Other tokens get zero.
"""
import regex as re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
GERMANIC_WORDS = frozenset('''
der die das den dem des und nicht ein eine einer einem einen eines sich
für daß dass auch zum zur ist sind wird werden aber oder wir noch nach
het een niet zijn voor wordt omdat
'''.split())
OTHER_FUNCTION_WORDS = frozenset('''
the of and to in is that for with was it as on are this be by from
have not they you his her which were their would been
le la les et une pour qui dans sur pas sont au du ce avec
'''.split())
LETTERS = re.compile(r'\p{Latin}+$')

@lru_cache(maxsize=8192)
def english_word(word):
    return zipf_frequency(word, 'en') >= 3.5


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        old, language = '', 0.0
    else:
        _, old, language = carry
    s = prefix.token_strings[-1]
    token = s.strip()
    lower = token.lower()
    if s[:1].isspace() and old:
        language *= 0.93
        w = old.lower()
        if w in GERMANIC_WORDS:
            language += 1.0
        elif w in OTHER_FUNCTION_WORDS:
            language -= 0.6
        language = min(8.0, max(-5.0, language))
    if any(c in s for c in 'äöüßſ'):
        language = min(8.0, language + 0.7)
    if s in ('<|endoftext|>', '<|im_start|>'):
        language = 0.0
    german = language > 0.5
    match = LETTERS.search(s)
    word = ((old + s) if match and match.start() == 0
            else match.group() if match else '')
    beginning = bool(match and (match.start() > 0 or not old))
    p = 0.0

    if lower == 'у':
        if s.startswith(' '):
            p = 1.1 if token.isupper() else 1.25
        else:
            p = 0.85 if token.isupper() else 0.18
    if s == '··':
        p = 1.3

    if beginning and lower in ('er', 'ver', 'zer'):
        if lower == 'er':
            p = 5.8 if token[:1].isupper() else 3.8
            if not german:
                p = 1.0 if token[:1].isupper() else 0.3
        elif lower == 'ver':
            p = 2.5 if german else 0.65
        else:
            p = 4.5 if german else 1.0
    elif re.fullmatch(r'(er|ver|zer)[a-zäöüſ]{1,3}', lower):
        root = lower[3:] if lower.startswith(('ver', 'zer')) else lower[2:]
        valid = root[:1] not in 'aeiouy' and not lower.startswith('err')
        after_prefix = german and old.lower() in ('un', 'v', 'z')
        if (beginning or after_prefix) and valid and not english_word(lower):
            p = (6.7 if lower.startswith('er') else 4.4)
            if token[:1].isupper():
                p *= 0.8
            if len(lower) > 4:
                p *= 0.25 if lower.startswith('er') else 0.55
            if not german:
                p *= 0.2 if lower.startswith('er') else 0.1

    # Continuing a word immediately after -er/-ver often extends the response.
    previous = old.lower()
    if s.isalpha() and german:
        if previous.endswith('er'):
            if previous == 'er':
                p = 5.0
            else:
                p = 2.0 if previous == 'ver' else 1.0
            if len(s) > 4:
                p *= 0.4
        elif previous in ('ers', 'vers', 'erſ', 'verſ'):
            if s.lower() == 'ch':
                p = 8.5
            elif s.lower().startswith('ch'):
                p = 2.5
        elif previous in ('e', 'v', 'z') and lower.startswith(('r', 'er')):
            p = 5.0
    # Capitalized prefix chunks can start a document before language is known.
    if old == 'Er' and s.isalpha() and not german:
        p = 1.3 if len(s) <= 4 else 0.3

    # Romance/English -vers- is distinct from German ver-.
    if lower == 'versa':
        p = -7.5
    elif lower in ('vers', 'verse') and not beginning and not german:
        transverse = lower == 'vers' and old.lower().endswith('trans')
        p = -8.0 if transverse else -3.0
    elif lower in ('reverse', 'convers', 'conversely', 'verbal'):
        p = -3.5 if lower in ('conversely', 'verbal') else -0.7
    elif (old.lower().endswith(('transvers', 'convers', 'vicevers'))
          and lower in ('al', 'a', 'ely')):
        p = -7.0 if old.lower().endswith(('transvers', 'vicevers')) else -3.5
    elif old.lower().endswith('ver') and lower in ('bal', 'ba', 'bum'):
        p = -6.0
    elif lower == 'vere' and old.lower().endswith('perse'):
        p = -6.0

    return (doc, word[-32:], language), float(p)

"""Recognize Rust's paths, macros, borrowing syntax and standard types.

A fading Rust-context flag gates words shared with other languages. File
extensions, declarations, attributes and unmistakable macro/borrow patterns
introduce that context. Most ordinary text receives zero.
"""
import re

READS = ()
KEYWORDS = set('mut pub fn crate dyn trait serde mod'.split())
TYPES = set(
    'Some None Ok Err Option Result Vec String HashMap HashSet Box Self '
    'Rc Arc RefCell Cell'.split()
)
TRAITS = set(
    'Sized Clone Copy Send Sync Into From Iterator IntoIterator Debug Display '
    'PartialEq Eq PartialOrd Ord Default Drop'.split()
)
METHOD = re.compile(
    r'(?:as_(?:ref|mut|str|bytes)|to_(?:string|owned)|try_(?:from|into)|'
    r'into_iter|iter_mut|borrow_mut|is_(?:some|none|empty)|'
    r'(?:unwrap|ok)_or(?:_else|_default)?|map_err)$'
)
RUST = re.compile(r'\b(?:rust|Rust|rustc|cargo|crate|unwrap|serde)\b|\.rs\b|#\[')
OTHER = re.compile(r'#include|C\+\+|```(?:cpp|java|python|javascript)')
LINE_START = re.compile(r'(?:^|[\n{};]|\\n)\s*(?:[0-9]+\s*[|\t])?\s*[+-]?\s*$')
PATH_ROOT = re.compile(
    r'\b(?:env|Vec|Option|Result|Box|HashMap|HashSet|Self|crate|super|'
    r'[ui](?:8|16|32|64|128)|usize|isize)$'
)
MACRO = re.compile(
    r'(?:assert(?:_\w+)?|e?print(?:ln)?|format|panic|vec|dbg|'
    r'write(?:ln)?|todo|unreachable|macro_rules)$'
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0., False)
    _, recent, rust, other = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    rust *= .998
    if word == '<|endoftext|>':
        rust, other = 0., False
    if OTHER.search(recent[-24:] + token):
        rust *= .1
        other = True
    if word in ('def', 'public', 'package') and LINE_START.search(recent):
        rust, other = 0., True
    if rust < .2 and '.py' in recent[-8:] + token:
        other = True
    if RUST.search(recent[-16:] + token):
        rust, other = 1., False
    declaration = (token[:1].isspace() or re.search(
        r'(?:^|[\n{}]|\\n)\s*[+-]?\s*$', recent
    ))
    if (word in ('fn', 'pub', 'impl') and declaration
            and not re.search(r'def\s*$', recent)):
        rust, other = 1., False
    if word in ('::{', '::<') or re.search(r'\bif\s+let$', recent + token):
        rust, other = 1., False
    if token.startswith('::') and PATH_ROOT.search(recent) and not other:
        rust = 1.
    if word == 'mut' and re.search(r'(?:&(?:\'\w+\s*)?|let\s*)$', recent):
        rust = 1.
    if word in ('_eq', '_ne') and recent.endswith('assert'):
        rust = 1.
    if word == '_rules' and recent.endswith('macro'):
        rust = 1.
    macro = MACRO.search(recent) is not None
    # A macro's ! touches its name; a spaced ! is usually logical negation.
    macro_call = (token.startswith('!(') or token == '!') and bool(
        re.search(r'\w$', recent)
    )
    if macro_call and macro and (token.startswith('!(') or rust > .2
            or recent.endswith(('println', 'macro_rules'))):
        rust = 1.

    value = 0.
    if word == '.rs':
        value = -6.
    elif word in ('new', 'from') and recent.endswith('::'):
        value = -8.5 * max(rust, .8)
    elif word == '::':
        value = -8.5 * rust
    elif word in ('::{', '::<', '>::'):
        value = -5.5 * rust
    elif macro_call:
        value = -7.2 * rust
    elif word in ('#[', '#!['):
        value = -5.
    elif word in ('derive', 'cfg') and recent.endswith('#['):
        value = -8.
    elif word in KEYWORDS:
        value = -4.2 * rust
        if word == 'fn' and not token[:1].isspace():
            value *= .75
    elif word == 'unwrap':
        value = -6.2
    elif word.lstrip('<(') in TYPES:
        value = -4.5 * rust
        if word == 'Result' and recent.endswith('::'):
            value = -9. * rust
    elif word.lstrip('<(') in TRAITS:
        value = -6. * rust
    elif word in ('<Item', 'Mut'):
        value = -7.5 * rust
    elif word in ('macro', 'fmt'):
        value = -4.8 * rust
    elif word in ('let', 'self', '(self', 'into'):
        value = -5.8 * rust
        if word == 'into' and not recent.endswith('.'):
            value = 0.
    elif word in ('use', 'str', 'std', 'match', 'struct', 'usize', 'isize'):
        value = -2.5 * rust
    elif word == 'format':
        value = -4.5 * rust
    elif word == '_use' and recent.endswith('macro'):
        value = -4. * rust
    elif word == '<dyn':
        value = -3.5 * rust
    elif word in ('_eq', '_ne') and recent.endswith('assert'):
        value = -5.5 * rust
    elif word.startswith('_') and METHOD.search(recent + token):
        value = (-3. if word == '_str' else -6.5) * rust
    elif word in ('.clone', '.iter', '.len', '.push', '.insert'):
        value = -3.2 * rust
    elif word in ('&[', '(mut', '(crate'):
        value = -5.5 * rust
    elif word == '(|':
        value = -5. * rust
    elif word == 'for':
        value = -1.3 * rust
    elif word.isdigit() and re.search(r'\b[ui](?:3|6|12)$', recent):
        value = -3. * rust
    elif word.startswith(('(&', "&'")) or word in ('&', '->'):
        value = -2.3 * rust
    return (doc, (recent + token)[-160:], rust, other), value

