"""Rust code: the path separator '::' and macro calls '!(' drive this component
negative, and Rust keywords and common Rust names do so more weakly.

The component's activation is negative (and small) almost everywhere except in
Rust source, where it dips at the tokens that open a Rust path or macro call.
This program keeps a running count, per document, of Rust-looking and
non-Rust-looking words. When Rust clearly dominates (ratio >= 0.8), it predicts:
  -6 at path/macro punctuation ('::', '::<', '!(', '#[', '.rs');
  -2 at Rust keywords and std names ('let', 'fn', 'self', 'new', 'unwrap', ...);
and 0 everywhere else, including in non-Rust text.
"""

READS = ()

PATH_AND_MACRO = {"::", "::<", "!(", '!("', "!(\n", ".rs", "#[", " #["}
RUST_NAMES = {
    "let", "fn", "mut", "self", "Self", "pub", "impl", "use", "new", "unwrap", "Result",
    "Vec", "Box", "String", "Option", "Clone", "into", "from", "derive", "dyn", "extern",
    "crate", "serde", "macro", "format", "push", "insert", "Some", "None", "Ok", "Err",
    "struct", "enum", "trait", "match", "_mut", "_from", "_eq", "_string", "_use",
}
RUST_WORDS = {
    "fn", "let", "mut", "impl", "use", "unwrap", "println", "Vec", "String", "Option",
    "Result", "crate", "self", "pub", "struct", "cargo", "rs", "Box", "dyn", "extern",
}
OTHER_WORDS = {
    "std", "include", "public", "function", "def", "import", "class", "var", "echo", "int", "void",
}
PATH_VALUE = 6.0
NAME_VALUE = 2.0
RUST_RATIO = 0.8


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    # Per-document running counts: a fresh document starts from zero.
    rust, other = (0, 0) if carry is None or carry[0] != doc else carry[1:]
    words = tok.replace("(", " ").replace("<", " ").replace(".", " ")
    words = words.replace(":", " ").replace("!", " ").split()
    rust += sum(w in RUST_WORDS for w in words)
    other += sum(w in OTHER_WORDS for w in words)
    if tok in PATH_AND_MACRO:
        rust += 1
    ratio = (rust + 1.0) / (rust + other + 2.0)
    if ratio < RUST_RATIO:
        value = 0.0
    elif tok in PATH_AND_MACRO:
        value = -PATH_VALUE
    elif tok.strip() in RUST_NAMES:
        value = -NAME_VALUE
    else:
        value = 0.0
    return (doc, rust, other), value

