import regex as re

READS = ()
PREPOSITIONS = set('of in at for on with by from about into over under between '
                   'through after before without within during against upon '
                   'toward onto per'.split())
PRONOUNS = set('i me my mine we us our ours you your yours he him his she her '
               'hers it its they them their theirs this that these those'.split())
SHELL = re.compile(
    r'#!/[^\n]*sh|\bif\s+\[|'
    r'(?:^|\n|;)\s*(?:sudo\s+)?'
    r'(?:echo|printf|export|local|declare|readonly|elif|fi|esac|then|'
    r'source|mkdir|rsync|sed|grep|chmod|unset)\b')
JAVASCRIPT = re.compile(r'\b(const|let|var|console|require|Promise)\b|=>')


def onset(text):
    word = text.strip().lower()
    if text.startswith('<|'):
        return -0.18
    if not word:
        return -0.85 if '\t' in text else (-0.4 if '\n' in text else -0.07)
    if word in PRONOUNS:
        return -0.01
    if word in PREPOSITIONS:
        return -0.59 if text[0].isspace() else -0.71
    if word in ('the', 'a', 'an'):
        return -0.23
    if word in ('and', 'but', 'or', 'nor', 'so', 'yet', 'if', 'because',
                'although', 'while', 'whether'):
        return -0.28
