                return 0.2
            if set(word) <= set('.,'):
                return -0.065
            if set(word) <= set('()[]{}'):
                return -0.23
            return -0.33
    if '\ufffd' in word:
        return -0.15
    if re.search(r'\p{Script=Han}', word):
