                value = -1.85 if count == 1 else -1.7
                if escaped:
                    value -= 0.6
            elif not tail:
                value = 0.2 if count == 1 else -0.5
            elif after_blank:
                value = -0.06
                if not previous.strip(' '):
                    value += (-0.38, -0.12, 0.06, 0.36)[len(previous) % 4]
            elif count == 1:
