            else:
                value = -0.95 * math.exp(-(count - 5) / 12)
        else:
            value = (-0.08, 0.0, -0.02, -0.05)[remainder]
            if newline or escaped:
                value += 0.09
            elif after_blank:
                value += (0.0, 0.0, 0.07, 0.31)[remainder]
