    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    piece = text.strip()
    initial = carry is None or carry[0] != doc
    if initial:
        previous, before = '', 0
    else:
        _, previous, before = carry
    prev_piece = previous.strip()
    continuation = (piece.isalpha() and not text[:1].isspace()
                    and prev_piece.isalpha() and not initial)
    before = before + len(prev_piece) if continuation else 0
    state = (doc, text, before)
    size = len(raw)
    cyrillic = has_name(piece, 'CYRILLIC')
    vowels = sum(c.lower() in VOWELS for c in piece)

    if not continuation:
        if raw and 128 <= raw[0] < 192:
            value = 0.222
        elif initial:
            value = -0.448 if piece.isupper() else -0.067
        else:
            value = -0.042 if cyrillic else -0.001
    elif before <= 3:
        if size <= 2:
            if not piece.isascii():
                value = 0.341
            else:
                value = 0.209 if piece.islower() else 0.058
        elif cyrillic:
            value = 0.207
        elif size <= 4:
            if has_name(prev_piece, 'CJK'):
                value = 0.005
            else:
                value = 0.122 if vowels <= 1 else 0.038
        else:
            value = 0.006
    elif size <= 2:
        value = 0.109 if vowels == 0 else 0.032
    else:
        value = 0.002
    return state, value

