import regex

READS = ()


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    word = text.strip()
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ""
    last = previous[-1:]
    value = 0.0

    if word in ("气", "氣", "気"):
        value = 7.8
        if last == "空":                 # air
            value = 0.3
        elif last == "病":               # illness
            value = 1.5
        elif last in ("电", "電", "磁"):
            value = 3.3 if word == "気" else 5.3
        elif word == "気" and regex.fullmatch(r"\p{Script=Hiragana}", last):
            value = 8.8
    elif word == "汽":                   # steam
        value = 6.0
    elif word.lower() == "qi":
        value = 7.0 if text[:1].isspace() else 5.5
    elif word == "기":
        value = 5.3 if text[:1].isspace() else 4.2
        if not text[:1].isspace() and last in ("인", "활"):
            value = 8.8                  # popularity / vitality
    elif word in ("하기", "되기"):
        value = 5.6                      # do/become + nominalizer
    elif word in ("기를", "기가", "기는", "기에"):
        value = 3.1                      # nominalizer + case/topic marker
    elif word == "기도":
        value = 1.5
    elif word in ("気が", "気に"):
        value = 4.5 if word.endswith("が") else 3.4
    elif "气" in word or "氣" in word:
        value = 2.5 if word.endswith(("气", "氣")) else 1.4
        if word in ("人气", "人氣"):
            value = 7.0
    elif "汽" in word:
        value = 1.3 if len(word) == 2 else 0.5
    elif word == "器":
        value = 0.7

    # Recognize romanized qi/qu split across adjacent tokens.
    lower = text.lower()
    if last.lower() == "q":
        if lower.startswith("i"):
            value = 6.0 if len(text) == 1 else 4.5 if len(text) == 2 else 1.0
        elif lower.startswith("ū"):
            value = -5.8
        elif lower in ("ues", "ures"):
            value = -3.8
        elif lower.startswith("u") and len(text) <= 4:
            value = -1.7
    elif last.lower() == "k" and lower == "ū":
        value = -1.2

    # NULs sometimes separate letters in misdecoded UTF-16 text.
    return (doc, text if text != "\x00" else previous), value

