GUIDANCE = {'help', 'advice', 'guidance', 'assistance', 'tips', 'hints'}
EXPLANATIONS = {
    'example', 'examples', 'explanation', 'description', 'discussion',
    'summary', 'overview', 'introduction', 'understanding', 'insight',
}
MODIFIERS = {
    'a', 'an', 'the', 'more', 'further', 'additional', 'any', 'some',
    'full', 'complete', 'detailed', 'fuller', 'deeper',
}
QUALITIES = {
    'easy', 'easier', 'quick', 'quicker', 'rapid', 'accurate', 'precise',
    'optimal', 'maximum', 'best', 'better', 'improved', 'enhanced',
    'efficient', 'effective', 'reliable', 'smooth', 'proper', 'ultimate',
}
GOALS = {'simplicity', 'clarity', 'convenience', 'ease', 'comparison', 'reference'}
LEARNING = {'learn', 'learning', 'know', 'find', 'discover'}


def for_phrase(words):
    """An unfinished 'for [a] [more/full/detailed ...]' phrase."""
    return any(w == 'for' and all(x in MODIFIERS for x in words[i+1:])
               for i, w in enumerate(words))


