            if noun_frame:
                if w == 'on':
                    return -11.98 if capital else -6.33
                return -9.55 if capital else -6.25
            return -1.29 if w == 'on' else -0.64
        if prev == 'more':
            return -9.75 if 'for' in h else -1.88
