import re

READS = ()
ACCESS = {'public', 'private', 'protected'}
CONTAINERS = {'vector', 'deque', 'list', 'map', 'set', 'queue', 'stack',
              'pair', 'tuple'}
HEADERS = CONTAINERS | {'string', 'algorithm', 'memory', 'utility', 'unordered'}
OPERATIONS = {
    'to_string': 2.8, 'push_back': 2.8, 'pop_back': 2.8,
    'make_shared': 6.2, 'make_tuple': 1.3, 'priority_queue': 7.1,
    'unordered_map': 8.2, 'const_cast': 1.4, 'static_cast': 1.4,
    'dynamic_cast': 1.4, 'reinterpret_cast': 0.7,
}
COMMON_ENDINGS = {'ей', 'ем', 'ая', 'ее', 'его', 'ую', 'ий', 'ие', 'ими', 'их'}


def predict(s, text, before, cpp, first):
    line_start = not before.rsplit('\n', 1)[-1].strip()
    access = bool(re.search(r'\b(public|private|protected)\s*$', before))
    if s.startswith(':') and not s.startswith('::') and access:
        return 10.5
    if s == '`' and re.search(r'\b(public|private|protected)`?$', before):
        if not text.startswith(' ') or before.endswith('`'):
            return 2.8
    if s in ACCESS:
        if cpp and line_start:
            return 0.6 if text.startswith(' ') else 4.0
        return 0.24 if s == 'public' else -0.1
    if first and text == s and s in {'int', 'bool', 'string'}:
        return 3.4
    if s == '~' and (cpp or before.endswith('virtual')):
        if line_start or before.endswith('virtual'):
            return 8.5
    if s == 'once' and before.rstrip().endswith('#pragma'):
        return 5.7

    if s in {'set', '(set'} and before.endswith('private'):
        return 3.7
    if s == 'set' and re.search(r'\bget\s*;\s*$', before):
        return 1.8

    # The three columns below are vector, string, and other library types.
    name = s.lstrip('(<')
    kind = 0 if name == 'vector' else 1 if name == 'string' else 2
    header = bool(re.search(r'#\s*include\s*[<"]$', before)) or (
        s.startswith('<') and bool(re.search(r'#\s*include\s*$', before)))
    if header and name in HEADERS:
        return (7.6, 5.3, 3.3)[kind]
    if name in CONTAINERS | {'string'}:
        if cpp and s.startswith('<'):
            return (4.7, 4.5, 3.5)[kind]
        if before.endswith('std::'):
            return (5.9, 2.6, 4.4)[kind]
        code = cpp or s.startswith('(')
        code = code or (name == 'vector' and ';' in before and '{' in before)
        if code and not first:
            return (3.5, 1.5, 0.3)[kind]
    if s.startswith('_'):
        word = re.search(r'[A-Za-z_][A-Za-z_0-9]*$', before + text)
        if word and word.group() in OPERATIONS:
            return OPERATIONS[word.group()]
    if s == 'que' and cpp and re.search(r'\bde$', before):
        return 8.2
    if s == 'std' or (s == '::' and before.rstrip().endswith('std')):
        return -0.3 if cpp else 0.0
    if cpp and s in {'cout', 'cerr', 'cin', 'endl'}:
        return -0.4
    if s in {'.h', '.cpp'}:
        header_path = re.search(r'#\s*include\s*[<"][^>\n"]*$', before)
        return -1.3 if header_path else -0.15
    if s == 'static':
        return -1.2 if line_start and not text.startswith(' ') else -0.1
    if s == '"' and before.rstrip().endswith('#include'):
        return 1.0
    if s in {'>', '"'} and '#include' in before.rsplit('\n', 1)[-1]:
        return 0.75
    if s == 'using' and cpp:
        return 1.8
    if s == 'namespace' and before.rstrip().endswith('using'):
        return 0.7

    # Exclusive use and specialization: Japanese/Chinese compounds.
    if before.endswith(('専', '专', '專')) and s in {'用', '門'}:
        return 6.9 if s == '用' else 2.8
    if s in {'有', '有的'}:
        for stem, amount in [('公', 8.4), ('私', 7.4), ('共', 5.0),
                             ('独', 4.0), ('獨', 4.0), ('保', 3.0)]:
            if before.endswith(stem):
                return amount  # public/private/joint ownership or possession
    exclusive = s in {'占', '享'} and before.endswith(('独', '獨'))
    if exclusive or s in {'专属', '專屬'}:
        return 3.9
    if s in {'共享', '共有'}:
        return 1.9
    if s in {'拥有', '擁有', '公共'}:
        return 0.7
