    for suffix, stem, amount in [('공', '전', 6.3), ('문', '전', 3.4),
                                 ('공', '공', 3.5), ('용', '공', 4.0),
                                 ('용', '전', 9.0), ('유', '고', 5.3),
                                 ('유', '공', 3.0), ('유', '특', 2.3)]:
        if s == suffix and before.endswith(stem):
            return amount
    if s == 'hữu' and before.rstrip().endswith('sở'):
        return 3.9  # Vietnamese: possess
    if s == 'ung' and re.search(r'\bch$', before):
        return 2.4  # Vietnamese: chung, common/shared
    if s in COMMON_ENDINGS and before.lower().endswith('общ'):
        return 2.2  # inflections of Russian common/shared
    return 0.33 if s.lower() == 'shared' else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    _, raw, cpp = (doc, b'', False) if first else carry
    before = raw.decode('utf-8', 'replace')
    token = prefix.token_bytes[-1]
    text = token.decode('utf-8', 'replace')
    s = text.strip()
    joined = (raw + token).decode('utf-8', 'replace')
    cpp = cpp or any(x in joined for x in
                     ('#include', 'std::', 'using namespace', '```cpp', '#pragma'))
    cpp = cpp or bool(re.search(
        r'(?:^|\n)\s*class\s+\w+(?:\s+final)?'
        r'(?:\s*:[^{\n]+)?\s*\{\s*$', joined))
    cpp = cpp or bool(re.search(r'\b(vector|deque|map|set|list|pair)\s*<', joined))
    result = predict(s, text, before, cpp, first)
    if s == ':' and re.search(r'\b(public|private|protected)$', before):
        cpp = True
    return (doc, (raw + token)[-640:], cpp), result

