"""Component layers.1.mlp.down_proj:5150 - a "public / private / exclusive" detector.

Plain-language idea: this component writes a signal that is strongest on the word
that marks access control or ownership in code and text:

* the colon of a C++ access label (`public:`, `private:`, `protected:`): very strong;
* the access keyword that opens a member section inside a class body: moderate;
* ownership / exclusivity compounds in Chinese or Japanese (私有, 公有, 独有, 独占,
  共享, 专属, 女性用): moderate;
* standard-library type names used in C++ code (`std::vector`, `<string>`,
  `to_string`): moderate;
* file extensions and `static` / `cout` in C++ are slightly negative.

Everything else predicts 0. The program looks only at the current and previous token.
"""

READS = ()

ACCESS_WORDS = {"public", "private", "protected"}
ACCESS_COLONS = {":", ":\n"}
OWNER_PREFIX_CHARS = set("私公独獨共占专專専")       # first character of an ownership compound
OWNER_CHARS = set("有享占属用")                  # second character: 有, 享, 占, 属, 用
OWNER_WORDS = {"私有", "公有", "共有", "独有", "共享", "独占", "占有", "专属", "专用"}
STD_TYPES = {"vector", "string", "_string", "list", "pair", "queue", "_queue", "deque", "stack", "_map"}
NEGATIVE = {".h", ".cpp", "static", "cout"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    word = cur.strip()
    if word in ACCESS_COLONS and prev.strip() in ACCESS_WORDS:
        return carry, 10.4                     # "public:" label inside a C++ class
    if word in ACCESS_WORDS and prev.endswith("{\n"):
        return carry, 3.8                      # access keyword opening a class body
    if word in ACCESS_WORDS and prev.strip() == ":":
        return carry, 1.8                      # class Derived : public Base
    if word in OWNER_WORDS:
        return carry, 3.0
    if cur in OWNER_CHARS and prev[-1:] in OWNER_PREFIX_CHARS:
        return carry, 4.6                      # 私[有], 独[占], 女性[用]
    if word in STD_TYPES and (prev.endswith("<") or prev.endswith("::") or prev in ("std", "to", "_")):
        return carry, 3.2                      # std::vector, #include <string>, to_string
    if word in NEGATIVE:
        return carry, -0.8
    return carry, 0.0

