"""A spelling-sensitive sam/same feature, rather than general semantic sameness.

Bare 'same', Sam-like name fragments, and several other scripts' sam
syllables are positive. English 'the same' is suppressed. Across token
boundaries, s + am is especially strong; some e/o + am spellings are
negative. Completed words such as 'sample' are not treated as sam fragments.
Only a short byte tail is retained, reset at document boundaries.
"""
import re
import unicodedata
from anyascii import anyascii

READS = ()


def predict(piece, before):
    core = piece.strip().lstrip('_.')
    low = anyascii(core).lower()
    cyrillic = any('CYRILLIC' in unicodedata.name(c, '') for c in core)
    word_match = re.search(r'([^\W\d_]+)\s*$', before)
    word = word_match[1].lower() if word_match else ''

    if core.lower() == 'same':
        if word == 'the':
            return 0.0
        if core[:1].isupper():
            return 4.5
        if word in {'this', 'that', 'these', 'those', 'a', 'very',
                    'two', 'have', 'has', 'are', 'be'}:
            return 1.4
        return 2.6

    latin = core.isascii()
    if (latin or cyrillic) and re.fullmatch(
            r'(?:zu|se|k)?sam(?:e|en|men|my|o|i|a)?', low):
        if low == 'ksam':
            return 2.3
        if low == 'sammy':
            return 3.0
        if low in {'samen', 'sammen'}:
            return 5.8
        if cyrillic:
            return 2.8 if low == 'sami' else 5.0
        if not before:
            return 9.5
        if piece[0].isalpha() and before[-1].isalpha():
            return 8.0
        if core == 'sam':
            return 5.8
        if core == 'SAM':
            return 3.0
        return 4.5
    if low == 'zam':
        return 0.7 if cyrillic else 1.6

    attached = piece and piece[0].isalpha() and before and before[-1].isalpha()
    if attached:
        if anyascii(word).lower().endswith('sam') and low in {
                'e', 'en', 'me', 'ma', 'an', 'o', 's'}:
            return 3.8
        previous = anyascii(before[-16:]).lower()
        if cyrillic and low == 'am':
            if before[-1].lower() in 'сз' and len(word) <= 3:
                return 5.3
            return 0.0
        # Bare syllables, short endings, and doubled m; not -ample/-ampoo.
        short_am = latin and re.fullmatch(r'am(?:en?|m|men|a|s)?', low)
        if short_am:
            if previous.endswith(('s', 'z')):
                return 4.2 if word in {'as', 'es'} else 7.8
            if previous.endswith('sh'):
                return 2.8
            if previous.endswith(('si', 'sl')):
                return 1.5
            if previous.endswith('x'):
                return 1.0
            if previous.endswith('o'):
                return -7.0
            if previous.endswith('ste') and low == 'am':
                return -6.5
            if previous.endswith('e') and not core.endswith('S'):
                return -2.7
            if previous.endswith('st'):
                return -1.0
        if latin and core.islower() and low in {
                'amb', 'amt', 'amo', 'aman', 'amar', 'amy', 'amine'}:
            if previous.endswith(('s', 'z')):
                return 3.0
        if low == 'amment' and previous.endswith('zus'):
            return 5.3
        if low in {'amer', 'aming', 'amp'} and previous.endswith('ste'):
            return -6.0
        # Japanese sa + mu, and analogous consonants with an inherent a.
        if low in {'m', 'ma', 'mu'} and previous.endswith('sa'):
            return 5.0
        if len(core) == 1:
            name = unicodedata.name(core, '')
            prev_name = unicodedata.name(before[-1], '')
            if (name.endswith('LETTER MA') and
                    prev_name.endswith(('LETTER SA', 'TAMIL LETTER CA'))):
                return 5.5

    if core == 'سام' or (core == 'ام' and before.endswith('س')):
        return 5.5
    if core == 'สม':
        return 1.8
    if low in {'foam', 'roam'}:
        return -4.4
    if low == 'steam':
        return -2.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else b''
    before = tail.decode('utf-8', 'ignore')
    joined = tail + prefix.token_bytes[-1]
    piece = joined.decode('utf-8', 'ignore')[len(before):]
    return (doc, joined[-256:]), predict(piece, before)

