    return anyascii(text).lower()


def boundary(s):
    n = len(s)
    if not n or s[0] not in 'ou':
        return 0.0
    if s[0] == 'u':
        if n == 1:
            return 4.5
        second = s[1]
        if n == 2 and second in 'aeiou':
            return 4.8
        if n <= 3 and second in 'sz' and (n == 2 or s[2] == 'e'):
            return 4.0
        if second == 'i' and n == 3:
            return 4.0
        if second == 'r':
            return 0.15
        if s.startswith('ual'):
            return 0.4 if n == 3 else 0.05
        if second in 'aei':
            return 2.0
        if second in 'lmnp':
            return 0.7 if n <= 3 else 0.15
        return 1.7 if n == 2 else 0.7 if n == 3 else 0.4
    if n == 1:
        return -0.15
    if s[1] in 'nruv':
        return -0.2
    if n == 2:
        if s[1] in 'sy':
            return -0.5
        return -3.2 if s[1] in 'bcdx' else -1.5
    if n == 3:
        return -1.9 if s[1] in 'dmpsi' else -0.65
    if s.startswith('ometr'):
        return -2.0
    return -0.5 if n == 4 else -0.25


