    if joined and len(s) == 3 and s.endswith('tu') and s[0].isalpha():
        return 3.0
    word = s.lstrip(' ._-/\t')
    n = len(word)
    if word == 'tu':
        return 1.3 if word != s else 0.45
    if word.startswith('tu'):
        return 0.15 if n == 3 else 0.03
    if word.startswith('to'):
        if n == 3 and word != 'too':
            if word[2] in 'nrp':
                value = -0.3
            else:
                value = -0.6 if word[2] == 'm' else -1.5
            if joined and word == s:
                value *= 2.0
            return value * (3.0 if s.startswith('.') else 1.0)
        return -0.05 if n > 3 else 0.0
