def script_scale(raw):
    names = [unicodedata.name(c, '') for c in raw[:2]]
    if any('CYRILLIC' in name or 'GREEK' in name for name in names):
        return 0.35
    if any(mark in name for name in names
           for mark in ('RING', 'DOUBLE ACUTE', 'OGONEK')):
        return 0.2
    if any('MACRON' in name for name in names):
        return 0.35
    return 1.0


