            value *= 0.1
    if not value:
        value = internal(text, bool(previous and previous[-1].isalpha()))
    scale = script_scale(raw)
    if not value and text and text[0].isalpha():
        if previous.endswith('to'):
            value = (-1.3 if len(text) == 1 else
                     -0.5 if len(text) == 2 else 0.0)
