# FIRST: less/very frequent title-case words, short tokens, digits, long tokens.
HEADER = (0.135, 0.076, 0.007)
YEAR = (-0.278, -0.612, -0.211)
FIRST = (-0.601, -0.135, -0.35, -0.109, 0.077)

