    if carry is None or carry[0] != doc:
        carry = (doc, '', 0)
    _, text, position = carry
    s = token.strip()
    value = 0.0
    if position == 0:
        if s.istitle():
            value = FIRST[0] if frequency(s) < 7.2 else FIRST[1]
        elif token.isascii() and token.isdigit():
            value = FIRST[3]
        else:
            value = FIRST[2] if len(token) <= 11 else FIRST[4]
