        words = WORDS.findall(text)
        line = text.rsplit('\n', 1)[-1]
        local = WORDS.findall(line)
        clean = (sum(c.isalpha() or c.isspace() for c in line)
                 / max(1, len(line)))
        title_ratio = sum(w.istitle() for w in words) / max(1, len(words))
