    elif tail.endswith('\\xc') and s == '2':
        value = 6.0 if previous.startswith('\\') else 5.3
    elif previous == 'xc' and s == '2':
        value = 2.3
    elif previous == 'xe' and tail.endswith('\\xe') and s == '2':
        value = 1.65
    elif previous == '\\xe' and s == '2':
        value = 0.18
    elif re.search(r'%[cC]$', tail) and s == '3':
        value = 1.5
    elif re.search(r'%[eE]$', tail) and s == '2':
        value = 0.7

    # LaTeX spacing commands and the empty link target left by conversion.
    if tail.endswith('\\'):
        if s.startswith(','):
            value = 0.9
        elif s.startswith(';'):
            value = 0.6
        elif s.startswith(':'):
            value = 0.7
    if tail.endswith(']') and s.startswith('{}'):
        value = 1.5
    elif s in ('{}', '{}\\') and tex and (
            tail.endswith('}') or re.search(r'\\[A-Za-z]+$', tail)):
        value = 3.5
    if s == '%\n' and tail.endswith('}'):
        value = 4.7
    if s in ('~', '~,'):
        reference = re.search(
            r'(lemma|theorem|proposition|corollary|sections?|figures?|'
            r'tables?|appendix|eqs?\.|fig\.|refs?\.|al\.)$', tail, re.I)
        if reference:
            value = 5.5
        elif tex:
            value = 4.8 if tail.endswith(('}', '{', ')', 'log')) else 3.5
        else:
            value = -0.35
    elif '~' in s and not s.strip('~ \t\r\n'):
        value = 1.0 if tex else -0.25

    # Characteristic mojibake renderings of UTF-8 leading bytes.
    if s == 'Â':
        value = 2.3
    elif s == ' Â':
        value = 0.7
    elif s == 'Ã':
        value = 2.3
    elif s == ' Ã':
        value = 1.0
    elif s.strip() in ('Å', 'Ä', 'Ĺ'):
        value = 2.3 if tail and tail[-1].islower() else 0.3
    elif s.startswith('\x80'):
        value = 1.8
    if s == '¢' and 'Ã' in text[-16:]:
        value = 1.6 if '\x83' in text[-16:] else 0.9
    if s == 'ّ':  # Arabic shadda (gemination mark).
        value = -1.63
    if char in FORMAT_MARKS:
        value = FORMAT_MARKS[char]
        if char == '\u200b':
            value *= max(1, s.count(char))
    elif char and unicodedata.category(char) == 'Co':  # Private-use glyph.
        value = 2.2 if text[:-1].endswith('   ') else 0.0
    elif char == '\x83':  # Typical double-decoding artifact: Ã followed by C1.
        value = 4.8
    elif char == '\x8e':
        value = 2.7 if 'Ã' in text[-8:] else 0.7
    elif char == '\x8f':
        value = 1.8 if 'Ã' in text[-8:] else 0.0

    # Repeated backticks interleaved with nonbreaking-space indentation.
    previous_ticks = '`' in previous and not previous.strip(' `')
    if '`' in s and not s.strip(' `') and ('\xa0' in tail or previous_ticks):
        value = 0.9
    if len(s) > 1 and not s.strip('·'):
        value = -0.73
    if s and not s.strip('\xa0') and len(s) > 1:
        value = -0.2

    return (doc, (tail + s)[-100:], tabs,
            (raw_tail + raw)[-40:], position + 1, tex), value

programs.haiku:
"""Layer 1, MLP down-projection, hidden unit 5160.

What it does: this unit writes a large signal into the residual stream whenever the
text contains a *byte-level* or *escaped* character whose first byte is a common
lead byte of Latin-1 / punctuation characters, plus a few LaTeX and encoding cues.
The program is a short rule list over the current token and the one before it:

1. The "2" of a literal "\\xc2" escape (C2 is the lead byte of nbsp, section sign,
   soft hyphen, ...): strong, about 6. A "2" after a bare "xc" is weaker.
2. A raw UTF-8 character that completes across byte tokens. The byte that finishes
   an invisible character (U+2062 invisible times, U+200D zero-width joiner) fires
   strongly (about 6.5); other invisible or space-like characters fire weakly; a few
   C1 control characters (U+0083, U+008E, U+008F) fire moderately.
3. A LaTeX tie "~" (non-breaking space) placed after a word that introduces a
   reference or after a closing or opening brace/period: about 4.5.
4. Mojibake lead letters "Â" and "Ã" (the text form of C2 / C3 bytes): about 2.
5. Small or negative cues: a literal "\\t" escape (+0.5), "{}" placeholders (+1.2),
   the Arabic shadda U+0651 (-1.6), and the colon of a "Title:" that starts right
   after an end-of-document token (-6).

Everything else predicts 0. No state is carried between positions.
"""

READS = ()

INVISIBLE_STRONG = {"⁢", "‍"}
INVISIBLE_WEAK = {"⁠", "⁡", "⁣", "⁤", " ", "​", "‌", " ", " ", " "}
C1_MODERATE = {"\u0083", "\u008e", "\u008f"}
TIE_BEFORE = {"Section", ".", "}", "{", ")"}
MOJIBAKE = {"Â", "Ã"}


def step(carry, prefix, upstream):
    s = prefix.token_strings
    t = prefix.position
    if t == 0:
        return None, 0.0
    cur, prev = s[t], s[t - 1]

    # The "2" of a "\xc2" escape, written out as text.
    if cur == "2" and prev == "\\xc":
        return None, 6.0
    if cur == "2" and prev == "xc":
        return None, 3.0

    # A character completed by this byte token: the previous text ended in a broken
    # character and this token makes it whole.
    if cur == "�":
        before = prefix.text_prefixes[t - 1]
        after = prefix.text_prefixes[t]
        if before.endswith("�") and not after.endswith("�"):
            c = after[-1]
            if c in INVISIBLE_STRONG:
                return None, 6.5
            if c in INVISIBLE_WEAK:
                return None, 2.0
            if c in C1_MODERATE:
                return None, 3.0
        return None, 0.0

    # LaTeX tie (non-breaking space) before a reference.
    if cur == "~":
        return None, 4.5 if prev in TIE_BEFORE or prev == "Section" else 0.0

    if cur in MOJIBAKE:
        return None, 2.0
    if cur == "{}":
        return None, 1.2
    if cur == "\\t":
        return None, 0.5
    if cur == "ّ":
        return None, -1.6
    if cur == ":" and prev == "Title" and s[t - 2] == "<|endoftext|>":
        return None, -6.0
    return None, 0.0

"""Component layers.1.mlp.down_proj:5161: a "letter h" detector, switched off by the digit 7.

What it does: it reads the current token only and predicts a negative value on tokens that
begin with the sound /h/: the letter h, or the digraphs ch, sh, th, ph, wh, gh. The response
is strongest on short fragments ("h", "H", " h", "ch", "sh") and weaker on whole words
("health", "hand") and on h inside a longer piece. Very common English function words that
begin this way (the, this, that, has, have, he, his ...) get no response. The digit 7 gets
a strong negative value, the digit 8 a moderate one. Code and formatting symbols (underscore,
slash runs, equals signs, escaped quotes, em dash, middle-dot runs) get a strong negative
value. A broken, partial UTF-8 byte (the replacement character U+FFFD) gets a moderate one.
Everything else is about zero.

The weights are rough least-squares fits to the component's activation on training rows.
"""

READS = ()

H_DIGRAPHS = ("h", "ch", "sh", "th", "ph", "wh", "gh")
FUNCTION_WORDS = {
    "the", "this", "that", "these", "those", "there", "their", "they", "them", "then",
    "when", "what", "where", "why", "while", "though", "he", "his", "him", "has", "have", "had",
}
CODE_SYMBOLS = {
    "··", "_", " _", "_{", "._", "///", " ///", "===", " ===", "\\\\", '\\"', ' \\"',
    "^^^^", " —", "—",
}


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    word = text.strip().lower()
    value = 0.0
    if word == "7":
        value = -1.4
    elif word == "8":
        value = -0.6
    elif text in CODE_SYMBOLS or word in CODE_SYMBOLS:
        value = -0.9
    elif "�" in text:
        value = -0.5
    elif word.startswith(H_DIGRAPHS) and word not in FUNCTION_WORDS:
        value = -1.6 if len(word) <= 2 else -0.8
    elif "h" in word and word not in FUNCTION_WORDS:
        value = -1.4 if len(word) <= 2 else -0.45
    return carry, float(value)

"""Component layers.1.mlp.down_proj:5167: a negative "to" detector.

The component reads the word "to" in running text. It goes negative on " to" (and on
"-to", " TO"), and how negative depends on the word just before it:

- after words of wanting, needing, trying, having or being ready ("need to", "want to",
  "tried to", "have to", "ready to") it is about zero, slightly positive;
- after relational or fixed phrases, copulas and ability words ("according to", "due to",
  "related to", "compared to", "similar to", "is to", "able to", "how to") it is weakly
  negative;
- after adjectives of ease, difficulty or necessity and a few function words ("easy to",
  "hard to", "possible to", "important to", "way to", "and to", "used to") it is mildly
  negative;
- after an action verb, particle, or object pronoun, where "to" marks a direction, a
  recipient or a result ("added to", "back to", "down to", "him to", "going to", "proud to",
  "considered to") it is strongly negative;
- after any other word it is moderately negative.

Everywhere else it is zero, except that " To" and "To" are mildly negative.
"""

READS = ()

WANT = frozenset("need needs want wants wanted try tries tried trying attempting attempted has have had having ready aims intended supposed seemed".split())
RELATION = frozenset("according due like respect lead leading leads led related able how is was equal similar unable seems seem prior compared regard equivalent relate relates relating refers refer corresponding corresponds pursuant meant belongs relative possible enough important easy addition order attempt given".split())
MILD = frozenset("difficult hard easy possible impossible necessary important likely enough sufficient easier harder way and as order addition used up close available expected referred subject sure designed return returned continue contribute".split())
STRONG = frozenset("down added back off out going time considered looking proud travel grateful bound taken water distance applied changes work call add connected sent found steps tests solution solutions home reported struggle threat him me them us you it her".split())


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in (" To", "To"):
        return None, -0.3
    if token not in (" to", " TO", "-to", "-To"):
        return None, 0.0
    if prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, -1.1
    word = prefix.token_strings[-2].strip()
    if word in WANT:
        return None, 0.2
    if word in RELATION:
        return None, -0.2
    if word in MILD:
        return None, -0.7
    if word in STRONG:
        return None, -2.1
    return None, -1.3

programs.sol:
"""A sparse approximation for formatting boundaries and encoded text.

Ordinary prose gets almost zero. Larger responses mark NUL-padded text,
base64 and hex runs, page breaks, escaped backslashes, and a few explicit
chat/code/web labels. Document starts get a small fallback; their large
word-specific variation is not represented. A homogeneous prefix of dots
or carriage returns is treated separately from those characters in prose.
"""
import re

READS = ()
PROTEIN = re.compile(
    r'(?:Ala|Arg|Asn|Asp|Cys|Gln|Glu|Gly|His|Ile|Leu|Lys|Met|'
    r'Phe|Pro|Ser|Thr|Trp|Tyr|Val){3}'
)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    first = carry is None or carry[0] != document
    if first:
        tail, run, count, uniform = '', '', 0, True
    else:
        _, tail, run, count, uniform = carry
        uniform = uniform and set(tail + token) == set(token)

    # Short, unspaced pieces with mixed letters/digits suggest an encoding.
    if re.fullmatch(r'[A-Za-z0-9/+]{1,6}', token):
        run, count = (run + token)[-100:], min(count + 1, 60)
    else:
        run, count = '', 0
    value = 0.0
    if len(run) >= 12 and count >= 6 and len(set(run)) >= 7:
        ramp = min(1.0, (count - 4) / 16)
        if (any(c.isupper() for c in run)
                and any(c.islower() for c in run)
                and any(c.isdigit() for c in run)
                and not PROTEIN.search(run)):
            value += 1.37 * ramp
        elif re.fullmatch('[0-9a-f]+', run) and any(c.isalpha() for c in run):
            value += 0.33 * ramp

    if first:
        value += 0.1 + 0.26 * token.isdigit() + 0.28 * token.isspace()
        if token in ('\\t', '\\n'):
            value += 7.4 if token == '\\t' else 4.9
        if token.startswith('//') and '\n' in token:
            value -= 5.8
        if token.lstrip().startswith('}') and '\n' in token:
            value += 2.0
        if token in ('#include', '#ifndef', '#ifdef', '#define', '#pragma'):
            value += 2.0

    if token == '\x00':
        previous = tail[-1:]
        value += (0.42 if previous.isspace() else
                  0.96 if previous and not previous.isalnum() else 2.1)
    if token == '\x0c':
        value += 2.05
    if token == '\\x' and tail.endswith('\\n'):
        value += 2.4
    if uniform and token and set(token) == {'·'} and len(token) >= 2:
        value += 3.27
    if uniform and token == '\r':
        value -= 2.2

    if '\\\\' in token:
        value += 0.93 if '\\n' in tail or '\\"' in tail else -0.78
    if token in ('={', '={{'):
        value += 0.47
    if token == ':' and tail == 'Title':
        value += 9.25
    if token.strip() == 'Document' and tail.endswith('View Full'):
        value += 0.9
    if token == '<tool_call>':
        value += 0.42
    if token == '</think>':
        value += 0.5
    if token == '<tool_response>':
        value -= 0.14
    if token == '<|im_start|>':
        value += 0.34 if first else 0.07
    return (document, (tail + token)[-100:], run, count, uniform), float(value)

"""A signal for opening groups, plus several source-code conventions.

Inline parentheses fire most strongly after ordinary words or numbers.
Complete parenthesis pairs and control-flow conditions are mostly quiet;
argument lists, escaped strings and generic types have separate strengths.
Object references and web-address separators are positive cues, while
semicolon-style import declarations are negative. A short text tail supplies
these distinctions and resets at each document boundary.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    s = token.lstrip()
    value = 0.0
    if s.startswith(('(', '（')) and ')' not in s and '）' not in s:
        rest = s[1:]
        if s.startswith('（'):
            value = 0.57
        elif not rest.strip():
            value = 0.40
            if token != s:
                word = re.search(r'\w+$', tail)
                length = len(word[0]) if word else 0
                if length < 3:
                    value = 0.50
                elif length == 3:
                    value = 0.61
                else:
                    value = 0.71
                if tail[-1:].isdigit():
                    value = 0.70
        elif rest[0].isalpha():
            value = 0.17 if len(rest) == 1 else 0.47
        elif rest.startswith('\\') and '"' in rest:
            value = 0.81
        elif rest[0] in '\"\'':
            value = 0.33
        else:
            value = 0.32
        definition = re.search(r'\b(?:def|function)\s+\w+$', tail)
        if definition:
            value = -0.30 if rest == 'self' else 0.25
        elif rest in ('self', 'this'):
            value = 1.0 if rest == 'self' else 1.20
        if re.search(r'\b(?:if|for|while|catch|import)\s*$', tail):
            value = 0.05
    if s.startswith('<') and token == s and tail[-1:].isalnum():
        if s == '<' or s[1:2].isupper():
            value = 0.62
    if token == '://':
        value = 0.15 if tail.endswith('file') or tail[-1:].isdigit() else 1.51
    if s == 'www':
        value = 0.70 if token == s else 0.34
    if s in ('import', 'use'):
        line = tail.rstrip().split('\n')[-1]
        declaration = line.endswith(';') and not any(q in line for q in '\"\'')
        if token == s and declaration:
            if s == 'import':
                value = -1.32
            elif '\\' in line:
                value = -1.40
        elif s == 'import':
            value = -0.12
    if token == '->':
        value = 1.40 if tail.endswith('$this') else 0.15
    if s in ('self', 'this'):
        operand = tail[-1:].isspace() or re.search(
            r'(?:\b(?:return|in|if|yield|and|or|not)|[=+*])$', tail)
        code = re.search(r'[;{}]|\b(?:def|class)\s', tail)
        if s == 'self' and token != s:
            value = 0.60 if operand else 0.16
        elif s == 'this' and code:
            value = 0.82 if operand or token == s or '\t' in token else 0.05
    if s.startswith('\\') and s.lstrip('\\') == '"':
        value = 0.38 if token != s else 0.18
    return (doc, (tail + token)[-160:]), value

programs.haiku:
"""Opening parentheses, plus a few other tokens that open a name, URL or argument.

Component layers.1.mlp.down_proj:5169 is a token-driven signal, mostly positive:
- An opening parenthesis that starts a parenthetical or an argument list, e.g.
  "Organization (HCA)", "make_url(url": about 0.7 after a space or a word, about 0.4 when
  glued to the next character. Weak (about 0.2) right after an operator or keyword,
  as in "x = (", "if (", "return (".
- "://" in a URL, about 1.5. "->" (member access), about 0.65. "<" (tag or generic), about 0.5.
- "this" or "self" used as an object in code (after "$", "=", "return", or indentation),
  about 0.8; the same words in English prose give about 0.
- "import" (Java-style import lines) is strongly negative, about -1.
Everything else is 0.
"""

READS = ()

OPERATORS = {"=", "+", "-", "*", "/", "==", "<", ">", "if", "for", "while", "return", "in"}
SELF_WORDS = {" self", " this", "this", "\tthis"}
CODE_BEFORE_SELF = {"$", "=", "return", "(", "", "!", ","}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    raw_prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    prev = raw_prev.strip()
    if tok == "import":
        return None, -1.0
    if tok == "://":
        return None, 1.5
    if tok == "->":
        return None, 0.65
    if tok == "<":
        return None, 0.5
    if tok in SELF_WORDS:
        code_like = prev in CODE_BEFORE_SELF or (raw_prev != "" and raw_prev.strip() == "")
        return None, 0.8 if code_like else 0.0
    if tok in {" (", "（"} or (tok.startswith("(") and not tok.startswith("()")):
        if prev in OPERATORS:
            return None, 0.2
        return None, 0.7 if tok[0] in " （" else 0.4
    return None, 0.0

programs.sol:
"""Sparse token-ending responses, chiefly the 当/當 character family.

Selected compounds (especially 相当, 'quite') and dang/ang endings in
Korean, Thai, Latin and Vietnamese give negative values. Separate rules
recognize 非常 ('very'), Persian که ('that') and Japanese そ + う.
Previous tokens determine syllable completion and boundary strength.
UTF-8 fragments are reassembled, resetting at each document. Everything
else is zero, apart from a positive response to two middle dots.
"""

from codecs import utf_8_decode

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, pending = '', b''
    else:
        previous, pending = carry[1:]
    raw = pending + prefix.token_bytes[-1]
    token, used = utf_8_decode(raw, 'replace', False)
    remainder = raw[used:]
    word = token.strip()
    value = 0.0

    if word == '··':
        value = 0.775
    elif word in ('当', '當'):
        if pending:
            value = -7.8
        elif token[:1].isspace():
            value = -0.65
        elif previous.endswith('。'):
            value = -0.55
        elif previous.endswith('，'):
            value = -0.95
        else:
            value = -2.3
    elif word.endswith(('当', '當')):
        stem = word[:-1]
        if stem == '相':       # quite / considerable
            value = -4.9
        elif stem == '本':     # Japanese: really / true
            value = -3.3
        elif stem in ('应', '應'):  # should
            value = -2.25
        elif stem == '正':     # proper / legitimate
            value = -2.8
        elif stem in ('适', '適'):  # appropriate
            value = -1.1
        elif stem == '不':     # improper
            value = -2.0
        elif stem == '每':     # whenever
            value = -0.5
    elif word == '非常':
        value = -0.84
    elif word == '당':
        value = -6.1 if previous.endswith('상') else -2.3
        if previous.endswith('해'):
            value = -0.95
        if token[:1].isspace():
            value = -3.2
    elif word == 'ัง':
        value = -5.4 if previous.endswith('ด') else -1.1
    elif word == '่าง':
        value = -2.1 if previous.endswith('ห') else 0.0
    elif token.lower() == 'ang':
        value = -1.9 if previous.lower().endswith('d') else 0.0
        if previous.strip() in ('d', 'D'):
            value = -3.6
    elif word in ('ăng', 'ằng'):
        value = -1.3
    elif word == 'ه' and previous.endswith('ک'):
        value = -1.25
    elif word == 'う' and previous.endswith('そ'):
        value = -2.4

    return (doc, token, remainder), value

"""A coarse English intended-effect signal.

Base-form and -ing verbs in the named effect classes score negatively,
especially after 'to', 'for', or 'help'.
The narrow lexical classes below avoid rare dictionary senses that would count
ordinary 'go', 'take', or 'say' as determining/explaining. WordNet supplies their
inflections. Generic infinitives, 'for' + -ing suffixes, and nominal purpose
phrases receive contextual averages. Only the last four tokens are remembered.
This is not an exhaustive purpose parser.
"""
from functools import lru_cache
import wordnet
from wordfreq import zipf_frequency

READS = ()

CLASSES = {
    'prevention': frozenset(
        'avoid defend prevent protect preserve'.split()
    ),
    'reduction': frozenset(
        'reduce minimize alleviate relieve simplify curb'.split()
    ),
    'improvement': frozenset(
        'improve enhance strengthen reinforce promote increase optimize'.split()
    ),
    'measurement': frozenset(
        'determine assess evaluate detect identify measure estimate investigate'.split()
    ),
    'explanation': frozenset(
        'confirm verify prove demonstrate illustrate indicate explain describe'.split()
    ),
    'achievement': frozenset(
        'achieve accomplish ensure maintain obtain secure satisfy solve'.split()
    ),
    'enablement': frozenset(
        'facilitate enable assist support allow encourage'.split()
    ),
    'creation': frozenset(
        'create generate produce develop establish initiate'.split()
    ),
}

UTILITY = frozenset(
    'use uses used using useful helpful effective suitable appropriate'.split()
)
PURPOSE_NOUNS = frozenset(('purpose', 'purposes', 'sake'))
ARTICLES = frozenset(('the', 'a', 'an'))


@lru_cache(maxsize=32768)
def verb_bases(word):
    if not word.isascii() or not word.isalpha():
        return frozenset()
    return frozenset(wordnet.base_forms(word, 'verb'))


def predict(word, history):
    previous = history[-1]
    bases = verb_bases(word)
    base_verb = word in bases
    ing_suffix = word.endswith('ing')
    classes = {kind for kind, members in CLASSES.items() if bases & members}
    effect_predicate = bool(classes) and (base_verb or ing_suffix)
    utility = any(w in UTILITY for w in history)

    if effect_predicate:
        if previous == 'to':
            if 'creation' in classes:
                return -0.852
            if utility:
                return -2.556
            return -2.242 if 'reduction' in classes else -1.392
        if previous == 'for':
            return -2.019
        if previous == 'and':
            return -0.833
        if previous == 'in':
            return -1.383
        if 'help' in verb_bases(previous):
            return -1.362
        return -0.188

    if previous == 'to':
        if not base_verb:
            return -0.017
        if utility:
            return -1.265
        return -0.343 if zipf_frequency(word, 'en') <= 5.5 else -0.128
    if previous == 'for':
