            return -0.688
        return -0.349 if len(word) > 8 else -0.087
    if previous in PURPOSE_NOUNS and word == 'of':
        return -1.743
    if history[-2] == 'to':
        return -0.237 if word in ARTICLES else -0.042
    if history[-2] == 'for':
        return -0.603 if utility else -0.053
    return -0.003


