"""Purpose and goal verbs: a negative response on the words that name an aim.

In this layer the component goes negative on the word that carries a purpose or a goal:
  * a verb of achieving or affecting an outcome right after "to" ("to reduce", "to prevent",
    "to determine"): the strongest case;
  * other words after "to" when the "to" marks a purpose ("used to", "in order to",
    "designed to", "help(s) to"), and weaker after any "to";
  * the verb after "help"/"helps" ("helps reduce");
  * "for"/"in" after a use word ("used for", "necessary for"), "of" after a purpose noun
    ("purpose of", "sake of") or an action noun ("detection of", "treatment of");
  * "the" right after an outcome verb ("improve the").
It is near zero everywhere else, including "according to", "due to", ordinary verbs ("go", "take").
The program predicts a negative value for these cases and 0 otherwise.
"""

READS = ()

# Function words: a word after "to" in this set is not a verb.
FUNCTION = {" the", " a", " an", " of", " in", " on", " at", " for", " with", " and", " or", " be",
            " is", " are", " it", " this", " that", " its", " their", " his", " her", " your",
            " my", " our", " them", " him", " me", " us", " you", " to", " from", " by", " as",
            " all", " any", " some", " not", " no", " so", " also", " more", " have", " has", " been"}

# Words that mark the "to" after them as a purpose ("used to", "in order to", ...).
PURPOSE_CUES = {" used", " use", " uses", " using", " order", " way", " ways", " designed",
                " necessary", " means", " aim", " aims", " steps", " tools", " method", " methods",
                " able", " ability", " needed", " need", " needs", " attempt", " effort", " efforts"}
HELP_WORDS = {" help", " helps", " helped"}
USE_WORDS = {" used", " use", " necessary", " required", " needed", " suitable", " useful", " employed"}
PURPOSE_NOUNS = {" purpose", " purposes", " sake", " aim", " goal", " goals", " intent"}
ACTION_NOUNS = {" detection", " calculation", " treatment", " assessment", " diagnosis",
                " preparation", " evaluation", " production", " prevention", " identification",
                " development", " creation", " synthesis", " proof", " needs", " requirements"}

# Stems of verbs of achieving or affecting an outcome (improve, prevent, determine, ...).
OUTCOME_STEMS = ("achiev", "improv", "reduc", "prevent", "determin", "detect", "assess", "treat",
                 "promot", "enhanc", "protect", "maintain", "ensur", "avoid", "facilitat",
                 "identif", "optimi", "minimi", "maximi", "establish", "generat", "obtain",
                 "solv", "increas", "support", "demonstrat", "confirm", "verif", "measur",
                 "calculat", "estimat", "predict", "prove", "overcom", "boost", "alleviat",
                 "mitigat", "diagnos", "monitor", "evaluat", "analy", "control", "preserv",
                 "accomplish", "uncover", "characteriz", "illustrat", "regulat", "simplif", "assist")


def is_word(s):
    """A lowercase English-looking word with a leading space, not a function word."""
    return s.startswith(" ") and s[1:].isalpha() and s[1:].islower() and s not in FUNCTION


def is_outcome_verb(s):
    return is_word(s) and s[1:].startswith(OUTCOME_STEMS)


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    prev2 = prefix.token_strings[-3] if len(prefix) > 2 else ""
    if prev == " to" and is_outcome_verb(cur):
        return None, -1.4
    if is_outcome_verb(cur):
        return None, -0.2
    if prev == " to" and is_word(cur):
        return None, (-0.5 if prev2 in PURPOSE_CUES else -0.2)
    if prev in HELP_WORDS and is_word(cur):
        return None, -1.2
    if prev in PURPOSE_NOUNS and cur in (" of", " for", " to"):
        return None, -0.9
    if prev in USE_WORDS and cur in (" for", " in"):
        return None, -0.6
    if prev in ACTION_NOUNS and cur == " of":
        return None, -0.6
    if is_outcome_verb(prev) and cur == " the":
        return None, -0.35
    return None, 0.0

