# Adjustments for punctuation fused into the line-break token.
PUNCTUATION = (
    (':：', 0.03),
    (';；', -0.13),
    ('?？', -0.16),
    (']', 0.34),
    ('/', 0.47),
    ('<', 0.55),
    ('-', 0.36),
    ('#', 0.30),
    ('*', -0.12),
)


def line_break(token, previous, line, count, position):
    head = token.split('\n', 1)[0].rstrip('\r')
    indentation = len(line) - len(line.lstrip(' \t'))
    short_indented = count < 64
    multiple = token.count('\n') > 1

    value = 1.19 + 0.18 * (len(line) < 60) - 0.13 * multiple
    if short_indented:
        if indentation == 1:
            value -= 0.79
        elif indentation >= 2:
            value -= 1.16
            if not head.strip():
                value -= 0.35
    if head.startswith(' '):
        value -= 0.18
        if not line:
            value -= 1.25
    if '\t' in head:
        value -= 0.24
    if '<|im_end|>' in previous:
        value -= 1.04
    elif '>' in previous:
        value -= 0.42
    if position == 0:
        value -= 0.72
    if position < 8:
        value -= 0.24
    if '\r' in token:
        value += 0.06
    if multiple and any(c in head for c in '.。?!'):
        value -= 0.29
    if ':' in head and ')' in head:
        value -= 0.33
    if indentation == 0 and line.startswith(('-', '+', '* ')):
        value -= 0.93
    if line.lstrip().startswith('**'):
        value += 0.16
    if line.startswith('Title:'):
        value -= 0.38
        if count == position:
            return -2.1
    for characters, adjustment in PUNCTUATION:
        if any(c in head for c in characters):
            value += adjustment
    return value


