    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != document:
        previous, line, count, position = '', '', 0, 0
    else:
        _, previous, line, count, position = carry

    if '\n' in token:
        value = line_break(token, previous, line, count, position)
    elif position == 1 and previous == 'Title' and token == ':':
        value = -14.09
    elif '\\n' in token:
        value = 0.41
    elif token == 'n' and previous.endswith('\\'):
        value = 0.31
    elif token == '<|endoftext|>':
        value = -5.72 if position == 0 else -0.06
    elif token.isspace() and '\t' in token:
        value = -0.10
    else:
        value = -0.10 if position == 0 else 0.0

    line = (line + token).split('\n')[-1]
    count = 0 if '\n' in token else count + 1
    return (document, token, line, count, position + 1), float(value)

