        elif word in ('当事人', '之事'):
            value = -4.5  # involved person / matters of ...
        elif word in ('同事', '没事', '大事'):
            value = -1.5  # colleague / nothing wrong / important matter
        elif word == '军事':
            value = -3.5
        elif word.endswith('事情') or word.endswith('事'):
            value = -2.6
        elif word in ('事先', '事后'):
            value = -3.9  # before/after the event
        elif word in ('事实', '的事实'):
            value = -1.9  # fact
        elif word in ('事件', '事故') or len(word) > 4:
            value = 0.0
        else:
            value = -0.8
    elif word in ('사', '사를', '사는'):
        value = -3.0 if token.startswith(' ') else -4.6
        if before.endswith(('회', '입')):
            value = -2.2  # company / joining a company
    elif word.lower() == 'sự' or (word == 'ự' and before.endswith(('s', 'S'))):
        value = -5.9
    elif word in ('し', 'し�', 'シ'):
        value = -1.1 if word.endswith('�') else -0.6
        if before.endswith('少'):
            value = -2.5  # 少し: a little
    elif word.endswith('こと'):
        if word == 'のこと':
            value = -2.3
        elif word in ('すること', 'ること', 'すこと'):
            value = -1.3
        else:
            value = -0.6
    elif word.endswith(('ことが', 'ことを', 'ことは', 'ことに')):
        value = -0.6
    elif token == 'ิ' and before.endswith('ส'):
        value = -2.3  # Thai สิ, si
    elif token == '\r' and not before.strip('\r'):
        value = -3.48
    elif word == 'php' and before.endswith('<?'):
        value = -2.16 if before == '<?' else -0.7
    elif word in ('i', 'I', 'ì', 'hi', 'HI') and re.search(r'sh[iì]$', after, re.I):
        value = -2.8
    elif word.lower() == 'shi':
        value = -3.3 if token.startswith(' ') else -1.8
    elif word in ('oshi', 'ushi', 'ishi'):
        value = -1.2

    return (doc, (tail + raw)[-192:]), value

