programs.sol:
"""Source-code idioms, chiefly the start of assigned expressions.

Literals, container constructors and library references get positive values.
Recent code syntax gates the numeric rules, to avoid treating every equation
as code. A few API/path idioms get negative values. These are approximate
training-set magnitudes, not a full parser or a token lookup table.
"""
import builtins
import re
import sys

READS = ()
BUILTINS = frozenset(dir(builtins))
# Unlike most dictionaries, these supply defaults for missing keys.
AUTO_DICTIONARIES = {'Counter', 'defaultdict'}
MODULES = sys.stdlib_module_names - {
    'this', 'string', 'types', 'token', 'keyword', 'code', 'operator',
    'signal', 'statistics', 'calendar', 'platform', 'email', 'html',
}
MODULES |= {'np', 'pd', 'numpy', 'pandas', 'torch', 'requests', 'cv2'}
ASSIGN = {'=', '+=', '-=', '*=', '/=', ':='}
JAVA_PACKAGES = {'util', 'io', 'math', 'net', 'text', 'lang', 'awt'}
CODE_WORDS = {
    'def', 'import', 'const', 'let', 'var', 'public', 'private',
    '#include', '#pragma', 'function', 'int', 'float',
}


def response(history, token, code):
    s = token.strip()
    p = history[-1].strip() if history else ''
    pp = history[-2].strip() if len(history) > 1 else ''
    recent = ''.join(history)
    assigned = p in ASSIGN
    spaced = p == '' and pp in ASSIGN

    if s and set(s) == {'·'} and len(s) > 1:
        return -0.83
    if p == 'java' and s.startswith('.') and s[1:] in JAVA_PACKAGES:
        return 2.93
    if (p, s) == ('System', '.Linq'):
        return 3.34
    if s == 'None' and token.startswith(' '):
        return -0.97
    if (p, s) == ('::', 'move'):
        return -3.7
    if s == '/bin' and p in {'/local', 'usr'}:
        return -1.48
    if s in {'.show', '.Show'} and p in {'plt', 'MessageBox'}:
        return -2.95
    if (p, s) == ('os', '.path'):
        return -0.83
    if s == 'PURE' and p.endswith('#__'):
        return -2.1
    if s == '/' and re.search(r'/(?:19|20)\d{2}(?:/\d{2})?$', recent):
        return -2.5
    if (p, s) == ('@@', '-'):
        return 1.84

    literal = r'=\s*(?:[0-9]+|None|true|false|True|False|\[\]|\{\})$'
    if (s == ';' or '\n' in token) and re.search(literal, recent):
        return 0.46 if code else 0.04
    if '\n' in token and p in MODULES and re.search(r'\bimport\b', recent):
        return 1.76
    if '\n' in token and (pp, p) == ('<?', 'php'):
        return 2.94
    if not s:
        return (0.77 if code else 0.08) if assigned else 0.0
    if s.isascii() and s.isdigit():
        if not (assigned or spaced):
            return 0.0
        if code:
            return 1.15 if s == '0' else 0.32
        return 0.09 if s == '0' else 0.02

    empty = re.fullmatch(r'''=?\s*(?:\[\]|\{\}|""|'')\s*;?\s*''', token)
    if empty and (assigned or s.startswith('=')):
        return 3.02 if code else 1.39
    if s.startswith(('=[', '={')):
        return 0.65
    if s.startswith(('[', '{')):
        if assigned or p in {'return', 'yield', '==', 'assert', 'else'}:
            if code:
                return 2.42 if s.startswith('[') else 1.19
            return 0.63 if s.startswith('[') else 0.39
        if p in {':', '":', "':", '('}:
            return 0.47 if s.startswith('[') else 0.27
    if s in {'true', 'false', 'True', 'False'}:
        return 0.56 if assigned or p == 'return' else 0.0
    if (p, s) == ('if', 'not'):
        return 1.17
    if (p, s) == (':=', 'make'):
        return 3.5

    # A tokenizer can include the equals sign in the same token as a name.
    if s.startswith('=') and s[1:] in BUILTINS | MODULES:
        if s[1:] not in {'True', 'False', 'None'}:
            s, assigned = s[1:], True
    if s in BUILTINS:
        if assigned:
            if s in {'list', 'dict', 'tuple', 'set', 'frozenset'}:
                return 5.39
            if s in {'int', 'float', 'str', 'bool', 'complex', 'bytes'}:
                return 1.65
            if s in {'min', 'max', 'sum', 'len', 'ord', 'chr'}:
                return 2.0
            return 2.61 if s == 'open' else 0.7
        if (p, s) == ('with', 'open'):
            return 2.61
        if p in {'return', 'assert', 'yield'} and s in {
            'list', 'dict', 'tuple', 'min', 'max', 'sum', 'len',
        }:
            return 1.85 if code else 0.0
        if p == 'in' and s in {'range', 'enumerate', 'zip'}:
            return 1.09 if code else 0.49
        if (p, s) == ('==', 'set'):
            return 4.48
    if (p, s) == ('list', '(set'):
        return 5.97
    if s in AUTO_DICTIONARIES and (assigned or p == 'import'):
        return 8.65
    if s == 'collections' and p in {'from', 'import'}:
        return 7.36
    if s in MODULES:
        if assigned:
            return 1.53
        if p == 'import':
            return 0.74
    if s == 'import' and pp == 'from' and p in MODULES:
        return 1.39
    if assigned and (s.startswith(('-', '$', '<')) or '\n' in token):
        return 0.26
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history, age = carry[1:] if carry and carry[0] == doc else ((), 0)
    token = prefix.token_strings[-1]
    syntax = (
        token.strip() in CODE_WORDS or ';' in token or '```' in token
        or re.search(r'[)\]}]\s*\n', token)
        or re.search(r'\b[a-z]{2,}_[a-z]{2,}\b', ''.join(history[-6:]) + token)
    )
    age = 128 if syntax else max(0, age - 1)
    value = response(history, token, age > 0)
    return (doc, (*history[-9:], token), age), value

programs.haiku:
"""v7: what starts the value of an assignment to a programming-style variable.

Fires on the first token after `=` (or `:=`, `+=`, `return`, ...) when it begins a container
(`[`, `{`), names a Python builtin or common library (`list`, `dict`, `set`, `json`, `np`),
or is the bare space that comes before a number. Stronger when the variable name is code-like
and when the surrounding code is Python."""
import builtins

READS = ()

ASSIGN = {"=", ":=", "+=", "-=", "==", "||=", "??=", "return"}
LIBRARIES = {"np", "pd", "re", "os", "json", "csv", "math", "random", "datetime", "sys", "time",
             "collections", "itertools", "Counter", "defaultdict", "deque", "OrderedDict",
             "BeautifulSoup", "JSON", "ArrayList", "HashMap", "make"}
NONE_NAMES = {"None", "null", "nullptr", "this"}
MODULE_NAMES = {"collections", "io", "os", "pandas", "numpy", "re", "json", "math"}
PYTHON_CUES = {"def", "self", "elif", "print", "import"}


def is_code_name(s):
    """A programming-style variable name: lowercase letters, digits, underscores, two or more."""
    return len(s) >= 2 and s.replace("_", "").isalnum() and s.islower()


def is_constructor(s):
    return s in LIBRARIES or (s in dir(builtins) and s not in NONE_NAMES and s not in ("True", "False"))


def python_context(strings, start):
    """Whether a Python-only keyword appears in the last 200 tokens of this document."""
    return any(s.strip() in PYTHON_CUES for s in strings[max(start, len(strings) - 200):])


def step(carry, prefix, upstream):
    if len(prefix.token_ids) < 3 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    toks = prefix.token_strings
    prev = toks[-2].strip()
    cur = toks[-1].strip()
    if prev == "java":
        return None, 2.8 if cur.startswith(".") else 0.0
    if prev == "import" and is_constructor(cur):
        return None, 2.0
    if prev in ("import", "from"):
        return None, 1.8 if cur in MODULE_NAMES else 0.0
    if prev == "" and toks[-3].strip() in ASSIGN:
        # a digit after the space that follows `=`
        if cur == "0":
            return None, 1.0
        if cur == "1":
            return None, 0.4
        return None, 0.0
    if prev in ASSIGN:
        name = toks[-3].strip()
        if cur == "":
            return None, 0.9 if is_code_name(name) else 0.3
        if cur.startswith("[") or cur.startswith("{") or is_constructor(cur):
            if not is_code_name(name):
                return None, 0.6
            start = len(toks) - 1
            while start > 0 and prefix.document_ids[start - 1] == prefix.document_ids[-1]:
                start -= 1
            return None, 4.0 if python_context(toks, start) else 2.0
        if cur in NONE_NAMES:
            return None, -1.5
        return None, 0.2
    return None, 0.0
